/**
 * 账号中心客户端面板。
 *
 * ## 控件与样式一律走 DSH 的设计体系
 *
 * 交互控件（按钮 / 开关 / 单选 / 下拉 / 弹窗 / 悬停提示 / 徽标 / 状态点）全部
 * 来自 `@deepseek-ai/dsh-client-ui-primitives`，本文件**不再自绘任何原生控件**；
 * 颜色 / 字体等样式值一律用 DSH design token（`--dsw-alias-*` 等），
 * 见 `account-hub-styles.js`。两条理由：
 *
 * 1. **类名复用不可能**：ui-primitives 的 CSS Module 类名在构建时被 hash
 *    （Vite `_local_hash_line` / tsdown `[hash]_[local]`），本插件拿不到它们的
 *    样式；要复用外观就只能复用组件本体。
 * 2. **零重复声明**：该模块经宿主 `PLATFORM_MODULES`（`packages/client/web/src/platform.ts`）
 *    注入共享模块表，与宿主同 loader 实例，属**隐式 baseline**
 *    （`packages/client/AGENTS.md` 明令禁止在插件 manifest 里重复声明它）。
 *    因此它既不在 `package.json` 的 peerDependencies，也不在 `dependencies`。
 *
 * ⚠️ 本文件是 **CommonJS 风格源码**：所有 UI 都用 `React.createElement` 显式构造，
 * 没有 JSX 构建步骤（`plugin-src/client/build.mjs` 只跑 esbuild 打包）。
 * 组件引用必须是**值绑定**（`Button`），不能写成 `<Button>`；且**不要**解构
 * `createElement`（既有单元测试的 react 占位模块只提供 `React.createElement`）。
 */

import * as React from 'react';

import {
  Button, DisclosureRow, IconApiOutlineRegular, IconBranchOutlineRegular, IconChevronDownOutlineRegular,
  IconPlusOutlineRegular, Input, Menu, Modal, Pill, RiskConfirmation, StateDot, Switch, Tag, Tooltip,
} from '@deepseek-ai/dsh-client-ui-primitives';

import { supportsCreditBalance, supportsDailyCheckin } from './credits-capabilities.js';
import { orderAfterDrop, dropPositionFromPointer } from './account-order.js';

export const ACCOUNT_HUB_RPC_CHANNEL = '/account-hub';

// 内联图标 base64
const CODEARTS_ICON = 'data:image/png;base64,'
const BUDDY_CN_ICON = 'data:image/png;base64,'
const BUDDY_ICON = 'data:image/png;base64,'

/**
 * LobsterAI 面板图标（内联 SVG data URL）。
 *
 * 用 SVG 而非 base64 PNG：现有三个图标是逆向客户端资源得到的 PNG，
 * 而 LobsterAI 没有可取的官方小图标 —— 内联 SVG 体积小、无色差，
 * 且在 `account-hub-styles.js` 的 `.dim-ah-providerIcon` 白底容器里显示清晰。
 *
 * 内容是**预先算好的 base64 字面量**，不用 `btoa()` 运行时拼接：
 * 该 bundle 由 esbuild 打包，目标环境未必提供 `btoa`（Node 有、但
 * 客户端 bundle 的运行时按 web 平台配置），字面量最稳妥。
 */
const LOBSTERAI_ICON = 'data:image/svg+xml;base64,'

/**
 * Trae CN 面板图标（内联 SVG data URL，与 LobsterAI 同款做法）。
 *
 * 来源：Trae CN 桌面客户端自带的品牌标识
 * `%LOCALAPPDATA%\Programs\Trae CN\resources\app\out\media\trae-logo.svg`
 * （397 字节，原样 base64 内联，未做任何改动）。用官方资源而不是自己画：
 * 同一目录下的 `ai-trae-sparkles*.svg` 用的是同一个品牌绿 `#32F08C`，
 * 可交叉印证这就是产品品牌色。
 *
 * 内容同样是**预先算好的 base64 字面量**（理由见上一条注释）。
 */
const TRAE_CN_ICON = 'data:image/svg+xml;base64,'

/**
 * Qoder 面板图标（内联 base64 PNG）。
 *
 * 来源：Qoder 官网首页 `<link rel="icon" type="image/png">` 指向的官方图标
 * `https://img.alicdn.com/imgextra/i4/O1CN01QkSxiCocd3D0prc8_!!6000000008124-2-tps-412-412.png`
 * （412x412 PNG，4990 字节，**原样内联、未做任何改动**，只做了 base64 编码）。
 *
 * 与 `LOBSTERAI_ICON` / `TRAE_CN_ICON` 那两条用官方资源、不自己画的理由一致；
 * 区别只在格式：本条是 base64 PNG（约 6.6 KB），与 `CODEARTS_ICON` /
 * `BUDDY_CN_ICON` 那几条体量同级，而 LobsterAI / Trae CN 是内联 SVG。
 * 内容同样是**预先算好的 base64 字面量**，不用 `btoa()` 运行时拼接
 * （理由见 `LOBSTERAI_ICON` 的说明）。
 *
 * 单独一个常量而不是复用别的图标：Qoder 与其余 provider 都不同源，
 * 共用任何一条都会让面板显示别家的品牌标识。
 */
const QODER_ICON = 'data:image/png;base64,'

const PROVIDERS = Object.freeze([
  { id: 'codearts', label: 'Codearts', icon: CODEARTS_ICON, logoClass: 'codearts' },
  { id: 'buddy-cn', label: 'Buddy CN', icon: BUDDY_CN_ICON, logoClass: 'buddy-cn' },
  { id: 'buddy', label: 'Buddy', icon: BUDDY_ICON, logoClass: 'buddy' },
  { id: 'lobsterai', label: 'LobsterAI', icon: LOBSTERAI_ICON, logoClass: 'lobsterai' },
  // 顺序 = 后端注册顺序（src/index.ts 里 Trae CN 服务在 LobsterAI 之后建立），
  // 也是能力矩阵里的登记顺序。
  //
  // 显示名一律用产品自身的叫法、**不带公司注记**（曾经是「CodeBuddy (腾讯)」
  // 「WorkBuddy (国际版)」「LobsterAI (有道)」「Trae CN (字节跳动)」）。
  // 图标常量名同样跟着产品走：`BUDDY_CN_ICON` 是中国版那份，`BUDDY_ICON` 是
  // 国际版那份（两者在改名时**没有**换过图标本体，只换了常量名与归属）。
  // `TRAE_CN_ICON` 归 `trae-cn`（TraeWork 曾是同一产品的第二条路径，官方已把
  // 该通道并入通用通道，那条 provider 已整体移除）。
  { id: 'trae-cn', label: 'Trae CN', icon: TRAE_CN_ICON, logoClass: 'trae-cn' },
  // Qoder：登录形态是**全新的** —— 浏览器设备流。
  //
  // 字段严格只有 id / label / icon / logoClass 四项：该条目的形态被
  // credits-capabilities.spec.ts 的 FULL 匹配器逐字锁死。
  { id: 'qoder', label: 'Qoder', icon: QODER_ICON, logoClass: 'qoder' },
  // Qoder **CN（国内版）**：与国际版**同协议双 region**（另一组 host、另一套
  // 出站身份值），登录形态同为浏览器设备流。
  //
  // ⚠️ **图标刻意复用 `QODER_ICON`**（不是新造一份）：两个 region 是**同一个
  //   品牌**，官方 `qoder.cn` 首页的 `rel="icon"` 指向的正是**同一张** alicdn
  //   PNG（与 qoder.com 逐字节同源），靠 `label` 与 `logoClass` 区分面板即可。
  //   （`qoder.cn` 另有一张内联 `favIcon.svg`，但 73 KB，远超内联预算，故不取。）
  { id: 'qoder-cn', label: 'Qoder CN', icon: QODER_ICON, logoClass: 'qoder-cn' },
]);

/**
 * ⚠️ **PAT 粘贴式登录形态已于 2026-09-21 按用户要求整体移除**，此处不再有
 * `PAT_LOGIN_PROVIDERS` / `providerPatLogin` / `normalizePatInput` /
 * `createAccountWithPat` / `PatLoginForm` / `LoginChoiceForm` 任何一项。
 *
 * 用户原话：「我说不要pat登录，只要浏览器登录了」。故 Qoder 两个 region 的
 * 「登录账号」（旧文案「+ 新建账号」）现在**只有一条路**：直接走 `createAccount()`
 * （浏览器设备流）。
 * 曾经的二选一选择器与它带来的 `loginChoiceOpen` 状态一并删除 ——
 * 保留了选择器却只留一个选项，等于多一次无意义的点击。
 *
 * ⚠️ **删的是 UI 入口，不是能力**：`src/qoder-auth.ts` 的 `login({ pat })` /
 * `loginWithPat` 一行未动（库层能力，与设备流共用写凭据逻辑），宿主
 * `src/account-hub-rpc.ts` 对 `account.create` 的 `hasPat` 分派也保留 ——
 * 那两处服务的是 headless / 测试 / 未来形态，不是本文件的死代码。
 *
 * 样式表里只服务这个表单的 PAT 输入框规则一并删除（曾经的 `.dim-ah-pat*`，已删 —— 留着就是死类）。
 */
/**
 * 积分能力判定见 `./credits-capabilities.js`。
 *
 * 之前这里有一份 `CREDITS_PROVIDERS = ['buddy-cn']`，只用来决定「一键领取积分」
 * 按钮是否渲染，却**没有**约束余额查询 —— 后者在面板挂载时对所有 provider
 * 无条件发起，于是 CodeArts 面板每次打开都在控制台报
 * `unsupported provider: codearts`，账号卡片的「积分」也永远是「查询失败」。
 * 现在两项能力（balance / dailyCheckin）都在同一张表里显式登记，并在请求前判定。
 */

/**
 * 登录弹窗的固定窗口名。
 *
 * 固定名字（而非 `_blank`）有两个作用：
 * 1. **重复点击不开新窗** —— 同名窗口会被浏览器复用，用户连点「登录账号」
 *    也不会攒出一堆登录标签页；
 * 2. 它与 `createAccount` 里 `window.open('')` 的空窗用的是同一个名字，因此
 *    「先开空窗占住用户手势、后填 URL」不会再多开一个窗口。
 *
 * **绝不能加 `noopener`**：`window.open(url, name, 'noopener')` 的返回值恒为
 * `null`，我们就再也拿不到窗口句柄，既无法 `location.replace` 填 URL，
 * 也无法在轮询结束后 `close()` 收尾。
 */
const LOGIN_WINDOW_NAME = 'dsh-account-hub-login';

/**
 * 登录窗口特性：固定尺寸、允许缩放与滚动条。
 *
 * 这些特性只在**该名字的窗口首次创建**时生效；后续同名 `window.open` 会复用
 * 已存在的窗口并忽略特性串 —— 正是我们要的「总是同一个登录窗」。
 */
const LOGIN_WINDOW_FEATURES = 'width=800,height=600,resizable=yes,scrollbars=yes';

function ProviderLogo({ provider }) {
  const p = PROVIDERS.find(p => p.id === provider);
  if (!p) return null;
  return React.createElement('span', { className: `dim-ah-providerIcon ${p.logoClass}` },
    React.createElement('img', { src: p.icon, alt: '', width: 20, height: 20 })
  );
}

/**
 * 悬停帮助文案的**唯一挂载点**。
 *
 * 迁移前这些文案挂在原生 `title=` 上（17 处）；原生 title 是浏览器自绘的
 * 提示框，样式不受主题控制、也不进 DSH 的设计体系，故统一改挂
 * ui-primitives 的 `Tooltip`。**文案本身一个字符都不改**：它是无障碍与
 * 「这个按钮到底做什么」的唯一说明来源。
 *
 * 为什么不逐处写 `React.createElement(Tooltip, { label: '…' })`：
 * 那会在 17 个调用点重复一遍同样的包装逻辑，且每加一处都要重新想一遍
 * 「包在哪个节点上」。收敛成一个包装函数后，调用点只需 `withHoverTitle(node, text)`，
 * 与迁移前 `title: text` 的写法同形 —— 差异最小、最不容易漏改。
 *
 * ⚠️ `Tooltip` 经 `React.cloneElement` 把事件与 ref 注入**单个**子元素
 * （见其源码：`children.props.onMouseEnter?.(e)`），因此 `node` 必须是一个
 * 元素、不能是数组或字符串。
 *
 * ⚠️ **子元素是组件时外面要套一层宿主 span**：`Tooltip` 给子元素注入的是
 * `ref`，而 ui-primitives 的 `Button` / `Tag` / `Pill` / `StateDot` / `Menu`
 * 都是普通函数组件（不是 `forwardRef`）—— 直接包它们的话 ref 进不去，
 * `Tooltip` 内部 `anchor.current` 恒为 `null`，悬停**永远不弹**（且 React 会
 * 警告「Function components cannot be given refs」）。
 * 故组件外面套一层 `display: inline-flex` 的宿主 `span` 当锚点：它不改变父级
 * flex / grid 的参与关系，也不给行内元素引入额外行高。
 *
 * ⚠️ 宿主标签（`dd` / `span` / `div`…）**不套**：`Tooltip` 的返回值是一个
 * Fragment（锚点 + 气泡），Fragment 不产生 DOM，故 `dd` 仍是网格容器的直接
 * 子元素 —— 套一层真 `span` 反而会把网格布局打断。
 *
 * ⚠️ `label` 为 `null` / `undefined` 时原样返回：迁移前「没有 title」的那些
 * 分支（如 `title: detail || undefined`）必须继续没有提示，不能凭空长出一个
 * 空提示框。
 */
function withHoverTitle(node, text) {
  if (node === null || node === undefined) return node;
  if (typeof text !== 'string' || text.length === 0) return node;
  const anchor = typeof node.type === 'string'
    ? node
    : React.createElement('span', { className: 'dim-ah-tipWrap' }, node);
  return React.createElement(Tooltip, { label: text }, anchor);
}

function formatTime(ts) {
  if (!ts || ts <= 0) return null;
  const d = new Date(ts);
  const now = Date.now();
  if (ts < now) return '已过期';
  const diff = ts - now;
  if (diff < 3600000) return `${Math.round(diff / 60000)} 分钟后`;
  if (diff < 86400000) return `${Math.round(diff / 3600000)} 小时后`;
  return d.toLocaleString('zh-CN', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
}

// 限流标记操作的提示文案与响应汇总函数（`RETEST_ALL_HELP` / `RESET_ALL_HELP` /
// `summarizeProbe`）已随面板上那对**供应商级**按钮一并删除；更早一轮已从账号卡片
// 删掉单账号的「重测 / 重置」及其 `RETEST_HELP` / `RESET_HELP`。至此界面上不再有任何
// 限流标记操作入口。
//
// ⚠️ 删的**只是 UI 入口**：宿主侧 `account.retest` / `account.reset` /
// `account.retestAll` / `account.resetAll` 四个 RPC 一行未动（库层能力，
// 服务 headless / 测试等其它调用方），见 `src/account-hub-rpc.ts`。

/**
 * 把积分余额格式化成一行文案。
 *
 * 保留两位小数：服务端下发的精确值就是两位（如 247.87），而整数版字段
 * 会截断成 247 —— IDE 顶部显示的 "Credits Balance 347.87" 用的是精确值，
 * 这里必须对齐，否则用户会以为插件算错了。
 */
function formatCredits(value) {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  // 整数不显示多余的小数位（100 而不是 100.00），有小数才保留两位
  return Number.isInteger(value) ? String(value) : value.toFixed(2);
}

/** 把一个包的明细格式化成 tooltip 的一行。 */
function formatPackageLine(pkg) {
  const remaining = formatCredits(pkg.remaining) ?? '?';
  const total = formatCredits(pkg.total) ?? '?';
  const parts = [`${pkg.active ? '' : '[已失效] '}${pkg.name || '未命名'}: ${remaining} / ${total}`];
  // 失效包显示它自己的失效时间，有效包显示本周期结束时间
  if (!pkg.active && pkg.expiredTime) parts.push(`失效于 ${pkg.expiredTime}`);
  else if (pkg.cycleEndTime) parts.push(`本周期至 ${pkg.cycleEndTime}`);
  return parts.join(' · ');
}

/**
 * 失败 outcome **没有** `message` 时的回退文案。
 *
 * 正常路径下服务端与 `collectClaimResults` 都会带上 message（含它们自己在
 * 客户端侧造的 failed，如「凭据未配置」）；真正会走到这里的只有**字段缺失
 * 或为空白**的异常响应。此时宁可显示一句固定的「领取失败」，也不能让那一行
 * 只剩一个光秃秃的账号名和 code。
 */
const CLAIM_FAILURE_FALLBACK = '领取失败';

/**
 * `unavailable` outcome **没有** `message` 时的回退文案。
 *
 * 与 `CLAIM_FAILURE_FALLBACK` 分开是刻意的：这一档**不是失败**，用「领取失败」
 * 会让用户去排查并不存在的问题。宿主侧（`src/trae-cn-credits.ts`）总会带上
 * message，这里只是字段缺失时的兜底。
 */
const CLAIM_UNAVAILABLE_FALLBACK = '服务端此刻暂不可签';

/**
 * 把一次 `unavailable` 的领取结果格式化成一行「账号：原因（code N）」。
 *
 * `unavailable` 是「服务端此刻暂不受理这次领取」——目前唯一的生产者是 Trae CN
 * 的 `9074`（名额/风控类拒绝，2026-09-23 真机定案）。它**不是失败**：正确动作是
 * 「什么都不做，等 4 小时后的自动重试」，故文案与色调都与 failed 行分开。
 *
 * 与 {@link formatClaimFailureLine} 的差异只有**回退文案**与语义标签 ——
 * `message` / `code` / `logid` 三件事的读法与渲染逐字相同（同一个服务端信封），
 * 故复用同一个格式化函数并传入不同的回退文案，而不是复制一份。
 */
function formatClaimUnavailableLine(result) {
  return formatClaimFailureLine(result, CLAIM_UNAVAILABLE_FALLBACK);
}

/**
 * 把一次失败的领取结果格式化成一行「账号：原因（code N）」，
 * 有 logid 时在末尾追加「· logid …」。
 *
 * 输入是 `credits.claimAll` 响应里 `results[]` 的一项
 * （`src/types.ts` 的 `RpcCreditsClaimAccountResult`）：`nickname` / `accountId`
 * 加判别联合 `outcome`（`src/credits.ts` 的 `ClaimOutcome`，失败分支为
 * `{ kind:'failed', code:number, message:string, logid?:string }`）。
 *
 * 服务端原文（`message`，如「当前参与用户太多，请稍后再试」）是用户判断
 * 「是风控限流、凭据失效还是活动结束」的**唯一依据** —— 只报一个「1 个失败」
 * 等于让用户去翻日志。`code` 一并带上（如 `code 9074`）便于对着服务端文档
 * 或插件日志核对；Trae CN 的 `9074` 就在 `src/trae-cn-errors.ts` 的退避码表里。
 *
 * **logid** 只有 Trae CN 会填（响应头 `x-tt-logid`），它是向服务端追查这一次
 * 请求的唯一线索 —— 用户报障时给出这一串，服务端才查得到当时发生了什么。
 * 其余协议没有这个字段，渲染逐字不变；为空串或缺失时**不追加**，避免行尾挂
 * 一个空的「logid 」。
 *
 * @param fallback - `message` 缺失或为空白时的回退文案。默认
 *        {@link CLAIM_FAILURE_FALLBACK}；`unavailable` 行传入它自己的文案
 *        （那一档不是失败，回退成「领取失败」会误导）。
 */
function formatClaimFailureLine(result, fallback = CLAIM_FAILURE_FALLBACK) {
  const outcome = result?.outcome ?? {};
  const label = result?.nickname || result?.accountId || '未知账号';
  const raw = typeof outcome.message === 'string' ? outcome.message.trim() : '';
  const message = raw !== '' ? raw : fallback;
  const code = typeof outcome.code === 'number' && Number.isFinite(outcome.code)
    ? String(outcome.code)
    : '未知';
  const base = `${label}：${message}（code ${code}）`;
  const logid = typeof outcome.logid === 'string' ? outcome.logid.trim() : '';
  return logid !== '' ? `${base} · logid ${logid}` : base;
}

/**
 * 从 `credits.claimAll` 的响应里取出失败账号的原因行（成功 / 已领 / 活动未开启
 * 都**不**产生行：那几类没有需要用户关注的信息）。
 *
 * `results` 缺失或不是数组时回退空数组，而不是抛错：摘要行本身仍然有效，
 * 不能因为拿不到明细就让整块提示消失（旧宿主或异常响应都不该把提示吞掉）。
 */
function claimFailureLines(res) {
  const results = res?.results;
  if (!Array.isArray(results)) return [];
  return results
    .filter((item) => item?.outcome?.kind === 'failed')
    // ⚠️ 必须写成箭头函数而不是 `.map(formatClaimFailureLine)`：`Array.map` 会把
    // **下标**作为第二个实参传进去，而本函数的第二个形参是回退文案 —— 直接传
    // 函数引用会让第一行的回退文案变成 `0`（「acc-9：0（code -1）」）。
    .map((item) => formatClaimFailureLine(item));
}

/**
 * 从响应里取出 `unavailable` 账号的原因行（「服务端此刻暂不可签」）。
 *
 * 与 {@link claimFailureLines} 分开收集、分开渲染：这一档**不是失败**，
 * 混进失败列表会让用户以为需要排查（凭据/设备），而正确动作是「等自动重试」。
 * 目前唯一的生产者是 Trae CN 的 `9074`（名额/风控类拒绝，2026-09-23 定案）。
 */
function claimUnavailableLines(res) {
  const results = res?.results;
  if (!Array.isArray(results)) return [];
  return results
    .filter((item) => item?.outcome?.kind === 'unavailable')
    .map(formatClaimUnavailableLine);
}

/**
 * `abnormal` outcome（签到异常：响应成功但积分未增加）**没有** `message` 时的回退文案。
 *
 * 与另外两个回退文案都不同：这一档服务端**没有错误**（它回了成功码），出问题的是
 * 「这次成功没有产生积分」。回退成「领取失败」会让用户去排查凭据/设备/网络 ——
 * 而这三样在本次请求里都是好的。
 */
const CLAIM_ABNORMAL_FALLBACK = '签到响应成功但积分未增加';

/** 余额数字的展示形态：非有限数一律视为「没有这个数字」（不是显示 0）。 */
function formatBalanceNumber(value) {
  return typeof value === 'number' && Number.isFinite(value) ? String(value) : null;
}

/**
 * 把一次 `abnormal` 的领取结果格式化成一行「账号：原因（签到前 X → 签到后 Y）」。
 *
 * ## 为什么它不复用 {@link formatClaimFailureLine}
 *
 * 那个函数按「服务端信封」渲染 `message` / `code` / `logid` 三件事，而本档**没有
 * code 也没有 logid**（服务端没报错）—— 复用会让每一行尾巴上挂一个「（code 未知）」，
 * 属于纯噪音。本档真正需要展示的是**前后两个余额数字**：没有它们，用户只看到一句
 * 「积分未变」，既判断不出是没发还是发少了，也没法拿去跟服务端核对。
 *
 * 两个数字任一缺失（旧宿主 / 异常响应）时**不显示那一段**，而不是显示
 * 「undefined → undefined」—— 那句话本身仍然成立（响应成功但积分没涨）。
 *
 * @param result - `results[]` 的一项，`outcome.kind === 'abnormal'`。
 */
function formatClaimAbnormalLine(result) {
  const outcome = result?.outcome ?? {};
  const label = result?.nickname || result?.accountId || '未知账号';
  const raw = typeof outcome.message === 'string' ? outcome.message.trim() : '';
  const message = raw !== '' ? raw : CLAIM_ABNORMAL_FALLBACK;
  const before = formatBalanceNumber(outcome.balanceBefore);
  const after = formatBalanceNumber(outcome.balanceAfter);
  const numbers = before !== null && after !== null ? `（签到前 ${before} → 签到后 ${after}）` : '';
  return `${label}：${message}${numbers}`;
}

/**
 * 从响应里取出 `abnormal` 账号的明细行（「签到异常」）。
 *
 * 与 {@link claimFailureLines} / {@link claimUnavailableLines} **三分**，互不混入：
 * 三者的用户动作完全不同（排查 / 等自动重试 / 等自动重试），混进一个列表会让用户
 * 把「不用管」的那两类也当成待处理的问题。
 *
 * 本档尤其**不能并进 claimed**：那正是「领取成功 +0」这个缺陷的形态 —— 数字与
 * 「成功」二字互相矛盾，而用户无从追查。
 */
function claimAbnormalLines(res) {
  const results = res?.results;
  if (!Array.isArray(results)) return [];
  return results
    .filter((item) => item?.outcome?.kind === 'abnormal')
    .map(formatClaimAbnormalLine);
}

/**
 * `undetermined` outcome（**无法判定**：Qoder 系空活动列表）**没有** `message`
 * 时的回退文案。
 *
 * 与另外三个回退文案都不同：它不是失败、不是服务端拒绝、也不是「已领」——
 * 而是**服务端什么都没说**。回退成「今天已领」是本次要修的缺陷本身（伪造一次
 * 签到），回退成「领取失败」会让用户去排查好的凭据。
 */
const CLAIM_UNDETERMINED_FALLBACK = '无法判定今天是否已领取';

/**
 * 把一次 `undetermined` 的领取结果格式化成一行「账号：原因」。
 *
 * ## 为什么它不复用 {@link formatClaimFailureLine}
 *
 * 那一档没有服务端错误可转述（HTTP 200、信封合法、**没有错误码**），复用会让
 * 每行尾巴挂一个「（code 未知）」—— 纯噪音。
 *
 * 文案**必须**说清「会自动重试」，因为这是本档唯一可执行的结论：用户什么都不用
 * 做，下一轮 sweep 会把不确定变成确定（届时活动若已开始就真的领到；若确实已领，
 * 服务端会回 `replayed:true` ⇒ 那时才显示「已领取」）。
 *
 * @param result - `results[]` 的一项，`outcome.kind === 'undetermined'`。
 */
function formatClaimUndeterminedLine(result) {
  const outcome = result?.outcome ?? {};
  const label = result?.nickname || result?.accountId || '未知账号';
  const raw = typeof outcome.message === 'string' ? outcome.message.trim() : '';
  return `${label}：${raw !== '' ? raw : CLAIM_UNDETERMINED_FALLBACK}`;
}

/**
 * 从响应里取出 `undetermined` 账号的明细行（「无法判定」）。
 *
 * 与另外三类明细**四分**：它们的用户动作各不相同（排查 / 等自动重试 / 等自动
 * 重试 / **无需动作、重试会自动完成判定**），混进一个列表会让用户把「不用管」
 * 的那几类也当成待处理的问题。
 *
 * 本档尤其**不能并进 already-claimed**：那会让界面显示「今天已领取」，而用户
 * 可能一分没领到 —— 这正是「qoder 假签到」在界面上的形态。
 */
function claimUndeterminedLines(res) {
  const results = res?.results;
  if (!Array.isArray(results)) return [];
  return results
    .filter((item) => item?.outcome?.kind === 'undetermined')
    .map(formatClaimUndeterminedLine);
}

/**
 * 「已有签到正在进行」的提示（**唯一文案**，三个入口共用）。
 *
 * 三种触发情形，用户看到的必须是同一句话：
 *  1. 本地互斥：`claimingRef` 已置真（自动补签 / 一键签到 / 单片签到任一在跑），
 *     此时按钮通常已 disabled，只剩键盘与程序化调用这两个旁路；
 *  2. 宿主互斥：`checkin.perform` 回 `busy: true` —— **另一路**签到在跑
 *     （4h sweep / 启动 sweep），本次一个 claim 都没发；
 *  3. 同一次点击被连点。
 *
 * ⚠️ 为什么必须**说出来**而不是静默 return：这三种情形都属于「点了没反应」的
 * 典型形态 —— 用户看到按钮弹回原状，无从判断是没点到、被挡、还是签到失败了。
 * 与自动补签（静默，用户只是进页面）刻意不同：那是被动触发，这是用户主动点的。
 *
 * 做成常量而不是两处各写一遍字面量：`details` 缺了会渲染成 `undefined` 行，
 * 三处写法漂移则同一件事会有三种说法。
 */
const CHECKIN_BUSY_NOTICE = { tone: 'warn', text: '已有签到正在进行，请稍候', details: [] };

/**
 * 把一次 `credits.claimAll` 的响应整理成 {@link ClaimNotice} 的 props。
 *
 * 摘要行只讲各档计数（「3 个账号领取成功（+300 积分），1 个失败」），
 * 失败账号的**服务端原文**另走 `details` —— 计数回答「有几个」，原文才回答
 * 「为什么」，而后者决定用户下一步做什么（等一会儿重试 / 重新登录 / 明天再来）。
 *
 * **`unavailable` 单独成行**（`unavailableDetails`，2026-09-23）：它不是失败，
 * 用户的正确动作是「什么都不做，稍后自动重试」，故既不并进失败计数、也不并进
 * 失败明细列表 —— 它的文案里已经写清了「稍后自动重试」。
 *
 * **`abnormal` 同样单独成行**（`abnormalDetails`，2026-09-24）：它也不是失败，
 * 但需要**独立可见** —— 并进 claimed 会让「领取成功 +0」这个缺陷再次隐形，
 * 并进 failed 会让用户去排查三种都好的东西（凭据 / 设备 / 网络）。
 *
 * 纯函数、不依赖 hooks，故可在单测里直接喂响应做整树深比较。
 * `res.summary` 刻意不做兜底：宿主必然返回它，真缺了就让异常走 `claimCredits`
 * 的 catch 显示错误提示，而不是静默降级成「没有可领取的账号」。
 */
function buildClaimNotice(res) {
  const summary = res.summary;
  const parts = [];
  if (summary.claimed > 0) parts.push(`${summary.claimed} 个账号领取成功（+${summary.totalCredit} 积分）`);
  if (summary.alreadyClaimed > 0) parts.push(`${summary.alreadyClaimed} 个今日已领取`);
  if (summary.inactive > 0) parts.push(`${summary.inactive} 个活动未开启`);
  // `?? 0`：旧宿主（不返回该字段）的响应不该让摘要行变成「NaN 个暂不可签」。
  const unavailableCount = summary.unavailable ?? 0;
  if (unavailableCount > 0) parts.push(`${unavailableCount} 个暂不可签`);
  // 同上：`abnormal` 也是新增字段（2026-09-24），旧宿主不返回它。
  const abnormalCount = summary.abnormal ?? 0;
  if (abnormalCount > 0) parts.push(`${abnormalCount} 个签到异常`);
  // 同上：`undetermined` 也是新增字段（2026-09-24）。
  const undeterminedCount = summary.undetermined ?? 0;
  if (undeterminedCount > 0) parts.push(`${undeterminedCount} 个无法判定`);
  if (summary.failed > 0) parts.push(`${summary.failed} 个失败`);
  return {
    tone: summary.failed > 0 ? 'warn' : 'ok',
    text: parts.length > 0 ? parts.join('，') : '没有可领取的账号',
    // 成功 / 已领 / 活动未开启都不产生明细行，故那些路径的渲染逐元素不变。
    details: claimFailureLines(res),
    // 暂不可签同样**不并入** details：它不是失败，混进去会让用户去排查。
    unavailableDetails: claimUnavailableLines(res),
    // 签到异常独立成段，理由见函数头。
    abnormalDetails: claimAbnormalLines(res),
    // 无法判定独立成段（2026-09-24）：它既不是失败也不是已领。
    undeterminedDetails: claimUndeterminedLines(res),
  };
}

/**
 * 领取结果的提示块：摘要行（`text`）+ 失败账号明细列表（`details`）。
 *
 * 形状与面板级通知行 `probeNotice` 完全一致（同 `.dim-ah-probeNotice`
 * + `.dim-ah-probeDetails`，同一个 `tone` 取值域），两处提示在界面上是同一种
 * 东西，不该长成两个样。
 *
 * **刻意抽成组件而不是在 ProviderPanel 里内联**：`ProviderPanel` 用了 hooks，
 * 单元测试加载不了它（react 不在依赖里，见 `tests/unit/account-hub-credit-balance-row.spec.ts`
 * 的说明）；抽出来才能对这棵树做**整树深比较**，把「成功路径一个字符都不变」
 * 变成可执行的断言，而不是靠肉眼看源码。
 */
function ClaimNotice({ tone, text, details, unavailableDetails, abnormalDetails, undeterminedDetails }) {
  return React.createElement('div', {
    className: 'dim-ah-probeNotice',
    'data-tone': tone,
    role: tone === 'error' ? 'alert' : 'status',
  },
  React.createElement('div', null, text),
  // 每个失败账号一行：账号名 + 服务端 message + code。文案已由
  // formatClaimFailureLine 兜底（message 缺失时给固定文案），这里只判有无。
  (details?.length ?? 0) > 0
    ? React.createElement('ul', { className: 'dim-ah-probeDetails' },
        details.map((line, i) => React.createElement('li', { key: i }, line)))
    : null,
  // 「暂不可签」单独一段，**不复用**失败明细那个列表：它与失败是两种东西，
  // 混在一个 <ul> 里用户会一并当成待处理的问题。
  (unavailableDetails?.length ?? 0) > 0
    ? React.createElement('ul', {
        className: 'dim-ah-probeDetails',
        'data-kind': 'unavailable',
      },
      unavailableDetails.map((line, i) => React.createElement('li', { key: i }, line)))
    : null,
  // 「签到异常」同样独立成段（2026-09-24）。它比暂不可签更需要被看见：它描述的
  // 是「响应说成功但账没动」，是本插件唯一会主动质疑服务端结论的一档。
  (abnormalDetails?.length ?? 0) > 0
    ? React.createElement('ul', {
        className: 'dim-ah-probeDetails',
        'data-kind': 'abnormal',
      },
      abnormalDetails.map((line, i) => React.createElement('li', { key: i }, line)))
    : null,
  // 「无法判定」独立成段（2026-09-24）：它既不是失败也不是「已领」。并入已领会
  // 让用户看到一句不成立的「今天已领取」—— 那正是「qoder 假签到」的界面形态。
  (undeterminedDetails?.length ?? 0) > 0
    ? React.createElement('ul', {
        className: 'dim-ah-probeDetails',
        'data-kind': 'undetermined',
      },
      undeterminedDetails.map((line, i) => React.createElement('li', { key: i }, line)))
    : null);
}

/**
 * 账号卡片上的积分余额行。
 *
 * 三种状态严格区分，不能混为一谈：
 * - 查不到（balance 为 null）→ 显示原因，不要显示成 0 积分
 * - 查到了但余额为 0 → 显示 0
 * - 还没有结果 → 显示"读取中"
 *
 * **单数字**：Trae CN 面板只查它自己那条路径能花的池（宿主按 provider 选池，
 * 见 `src/account-hub-rpc.ts` 的 `credits.balances` 分支），返回的 `total` 与
 * `packages` 都**只含该池**，故这里就是普通的一个数字，与其他 provider
 * 走的是同一条渲染路径。
 *
 * 历史上这里消费过一个超集字段 `workTotal` 来渲染「通用 X / Work Y」两段，
 * **已删除**：那个字段与它所服务的双段渲染一起没了（同一处显示两池时，
 * 永远有一段是那个面板花不掉的）。余额对象从此与 `CreditBalance` 逐字段同构，
 * 本组件不再需要任何 provider 专属分支。
 */
function CreditBalanceRow({ balance, error, loading }) {
  if (loading) {
    return React.createElement('div', { className: 'dim-ah-metaRow' },
      React.createElement('dt', null, '积分'),
      React.createElement('dd', { 'data-tone': 'muted' }, '读取中…'));
  }
  if (error || !balance) {
    return React.createElement('div', { className: 'dim-ah-metaRow' },
      React.createElement('dt', null, '积分'),
      withHoverTitle(
        React.createElement('dd', { 'data-tone': 'warn' }, error || '查询失败'),
        error || '查询失败'));
  }
  const total = formatCredits(balance.total) ?? '0';
  // 明细放进悬停提示，不占版面；账号卡片本身已经信息密集了。
  // `detail` 为空串时 withHoverTitle 原样返回 dd —— 与迁移前
  // `title: detail || undefined` 同一语义（没有明细就不长提示框）。
  const detail = (balance.packages || []).map(formatPackageLine).join('\n');
  const all = balance.packages || [];
  const activeCount = all.filter(p => p.active).length;
  return React.createElement('div', { className: 'dim-ah-metaRow' },
    React.createElement('dt', null, '积分'),
    withHoverTitle(React.createElement('dd', { className: 'dim-ah-creditValue' },
      React.createElement('strong', { className: 'dim-ah-creditTotal' }, total),
      all.length > 1
        ? React.createElement('span', { className: 'dim-ah-creditPackages' },
            `${activeCount}/${all.length} 个资源包有效`)
        : null,
      // 失效额度单独提示：它们仍在服务端响应里，但不计入上面的数字
      balance.expiredTotal > 0
        ? React.createElement('span', { className: 'dim-ah-creditExpired' },
            `另有 ${formatCredits(balance.expiredTotal)} 已失效`)
        : null), detail));
}

/**
 * 账号卡片。
 *
 * ⚠️ 卡片上**只有**签到 / 启用停用 / 删除三类按钮：单账号的「重测」「重置」已按
 * 用户要求移除，面板标题栏的供应商级「重测所有 / 清除限额」后来也一并删除 ——
 * 界面上已不存在任何限流标记操作入口。宿主侧的 `account.retest` / `account.reset` /
 * `account.retestAll` / `account.resetAll` 四个 RPC **一行未动**（它们是库层能力，
 * 服务 headless / 测试等其它调用方），删的只是 UI 入口。
 *
 * `drag` 是本卡片的拖拽接线（由 `ProviderPanel` 的 `dragPropsFor` 构造）：
 * 传入 `undefined` 或 `{ enabled: false }` 时卡片**完全不渲染**拖拽属性与
 * 抓取柄 —— 只有一个账号、或顺序提交在途时就是这个形态。
 */
function AccountCard({ account, index, order, onToggle, onDelete, busy, credits, creditsLoading, showCredits, showCheckin, checkedIn, checkingThisAccount, onCheckin, drag }) {
  const rateLimits = account.modelRateLimits
    ? Object.entries(account.modelRateLimits).filter(([, v]) => v > Date.now())
    : [];
  const expired = typeof account.expiresAt === 'number' && account.expiresAt > 0 && account.expiresAt <= Date.now();
  // 拖拽状态与回调统一由 ProviderPanel 掌管（只有它知道整个列表的顺序）。
  const dragProps = drag || {};

  return React.createElement('div', {
    className: 'dim-ah-accountCard',
    'data-enabled': account.enabled,
    // 正在被拖动的卡片：半透明（样式表按 data-dragging 上 opacity）
    'data-dragging': dragProps.isDragging ? 'true' : undefined,
    // 插入位置指示：before 画在卡片上方、after 画在下方 —— 必须与实际落点
    // 一致，否则用户按指示拖放却得到相反的结果。
    'data-dropBefore': dragProps.isDropTarget && dragProps.dropPosition !== 'after' ? 'true' : undefined,
    'data-dropAfter': dragProps.isDropTarget && dragProps.dropPosition === 'after' ? 'true' : undefined,
    // 整卡可拖：抓取柄之外也能拖，手感更好；卡片内的按钮点击不受影响
    // （HTML5 拖拽需要按住移动，普通 click 不进拖拽路径）。
    draggable: dragProps.enabled ? 'true' : undefined,
    onDragStart: dragProps.onDragStart,
    onDragEnd: dragProps.onDragEnd,
    onDragOver: dragProps.onDragOver,
    onDrop: dragProps.onDrop,
  },
    React.createElement('div', { className: 'dim-ah-accountTop' },
      // 抓取柄 + 序号：序号即自动选号优先级，让「拖到第一位」的含义明确 ——
      // 顺序不是装饰，它直接决定下一个请求用哪个账号（见 account-order.js）。
      dragProps.enabled
        ? React.createElement('span', {
            className: 'dim-ah-dragHandle',
            'aria-hidden': 'true',
          }, '⠿')
        : null,
      dragProps.enabled
        ? React.createElement('span', { className: 'dim-ah-accountOrder' },
            String((order ?? index ?? 0) + 1))
        : null,
      // 状态点：绿=已启用、灰=已停用（`StateDot` 的 done / idle 两档）。
      // 迁移前是一个自绘的 8px 圆点 + `title`；现在两者都来自设计体系，
      // 提示文案原样保留。
      withHoverTitle(React.createElement(StateDot, {
        state: account.enabled ? 'done' : 'idle',
      }), account.enabled ? '已启用' : '已停用'),
      React.createElement('span', { className: 'dim-ah-accountName' },
        account.nickname || account.id),
      React.createElement(Tag, {
        tone: account.enabled ? 'success' : 'neutral',
      }, account.enabled ? '已启用' : '已停用')),
    React.createElement('dl', { className: 'dim-ah-accountMeta' },
      React.createElement('div', { className: 'dim-ah-metaRow' },
        React.createElement('dt', null, '凭据'),
        React.createElement('dd', null, React.createElement('code', null, account.credentialRef))),
      React.createElement('div', { className: 'dim-ah-metaRow' },
        React.createElement('dt', null, '有效期'),
        React.createElement('dd', { 'data-tone': expired ? 'warn' : undefined },
          account.expiresAt
            ? `${formatTime(account.expiresAt) || '未知'}${account.refreshable ? ' · 自动续期' : ''}`
            : '未知')),
      // 不支持积分余额的 provider（CodeArts）不渲染该行：留着它只能显示
      // 「查询失败」，而失败原因是「这个 provider 根本没有此接口」——
      // 与其展示一条无法修复的错误，不如不展示。
      showCredits
        ? React.createElement(CreditBalanceRow, {
            balance: credits?.balance ?? null,
            error: credits?.error,
            loading: creditsLoading,
          })
        : null),
    rateLimits.length > 0
      ? React.createElement('div', { className: 'dim-ah-rateLimits' },
          React.createElement('span', { className: 'dim-ah-rateLimitsLabel' }, '限额重置'),
          rateLimits.map(([modelId, resetAt]) =>
            withHoverTitle(React.createElement(Tag, {
              key: modelId,
              tone: 'warning',
              className: 'dim-ah-ttlBadge',
            }, `${modelId} · ${formatTime(resetAt)}`), `模型 ${modelId}`)))
      : null,
    React.createElement('div', { className: 'dim-ah-accountActions' },
      showCheckin
        ? React.createElement(Button, {
            variant: 'outline',
            size: 'sm',
            className: `dim-ah-iconBtn${checkedIn || checkingThisAccount ? '' : ' dim-ah-iconBtn-light'}`,
            'aria-label': checkedIn ? '已签到' : checkingThisAccount ? '签到中' : '签到',
            // `busy` 是面板级忙碌 —— 由调用方传入，`ProviderPanel` 已把它算成
            // `claiming`（签到进行中）。限流标记那对供应商级按钮删除后，面板级忙碌
            // 只剩签到这一个来源，`probeBusy` 随之消失。
            // ⚠️ 此前它**不含**签到本身：一键签到或自动补签在跑时，单片按钮看起来
            // 可点、点下去却被 `claimingRef` 静默挡掉 —— 「点了没反应」的缺陷形态。
            // `checkingThisAccount` 是本账号自己的签到中态（本卡片局部），
            // 与面板级 `claiming` 是两个维度，两个都要判。
            disabled: busy || checkedIn || checkingThisAccount,
            onClick: () => onCheckin(account.id),
          }, checkedIn ? '✓' : checkingThisAccount ? '◐' : '✉')
        : null,
      React.createElement(Button, {
        variant: 'outline',
        size: 'sm',
        onClick: () => onToggle(account.id, !account.enabled),
      }, account.enabled ? '停用' : '启用'),
      React.createElement(Button, {
        variant: 'outline',
        size: 'sm',
        className: 'dim-ah-btn-danger',
        onClick: () => onDelete(account.id),
      }, '删除')));
}

/**
 * 上下文窗口的展示文案（token 数 → `1M` / `168K`）。
 *
 * ## 为什么是 1000 进制（不是 1024）
 *
 * 这个数只在 UI 里给用户**扫一眼**用，而用户脑子里的参照系是**厂商口径**：
 * OpenAI / Anthropic / 字节的模型卡一律按 1000 进制写（200K、1M），
 * Trae 客户端自己的「168K / 1M」也是这个口径。用 1024 进制缩写反而会和
 * 用户手边所有别处的数字对不上 —— 那正是上一版「只在能被 1024 整除时才缩写、
 * 否则原样显示 168000」的毛病：`168000` 这种目录真实值在界面上是一串裸数字，
 * 既难扫视、又和客户端显示的 `168K` 看起来像两个不同的东西。
 *
 * ## 精度：精确值不丢，只是挪到 title
 *
 * 缩写必然是近似（`1048576` → `1M`，误差 4.9%），所以**精确值仍然可见** ——
 * 调用方把它放进 `title`（`默认档 · 168000 token`）。缩写负责扫视，tooltip
 * 负责核对，这与「档位值精确等于目录公布值」的原则并不冲突：真正决定压缩
 * 时机的是宿主读的那个数字，不是这行文案。
 *
 * - `1_000_000` → `1M`、`1_500_000` → `1.5M`、`1_048_576` → `1M`
 * - `168_000` → `168K`、`200_000` → `200K`、`119_040` → `119K`
 * - `999` → `999`（不足 1K 原样输出）
 */
function formatCapacity(value) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) return '';
  if (value >= 1e6) {
    // 去掉多余小数：`1.0M` → `1M`，`1.5M` 保留一位。
    const millions = Math.round(value / 1e5) / 10;
    return `${millions}M`;
  }
  if (value >= 1e3) return `${Math.round(value / 1e3)}K`;
  return String(value);
}

/**
 * 一行模型**可选的上下文窗口档位**（升序去重）；`null` = 没有档位可选。
 *
 * ## 两个数据源，优先多档数组
 *
 * 1. `contextTiers`（Host 归一后的**完整档位表**，≥2 项才带）—— 档数不限：
 *    Qoder 真机 `[200000, 400000, 1000000]` 三档、Buddy 的 `supportedLengths`
 *    两档、Trae CN 的 `dev` / `max` 也会被 Host 一并归一进这张表；
 * 2. 只有 `maxContextWindow` 的两字段形态 —— **旧 Host**（升级插件后页面还没重建
 *    bundle 的窗口期）以及「本轮目录只公布了 max」的防御路径。
 *
 * 默认档（`contextWindow`）**并入**列表：目录给的默认档理论上可能不落在档位表里
 * （Buddy 的 `min(maxInputTokens, 档位表最大档)` 就会产出这种组合），不并入则
 * 「当前是默认档」这个状态在界面上无法表达（radio 全不选中）。
 *
 * ⚠️ **判据只看数据，不看 provider 名**：数据在，档位列就在；数据不在（LobsterAI /
 * CodeArts 的目录只有一个窗口，或目录未达）就整列不渲染 ——
 * 宁可少一个控件，也不给一个切过去毫无效果的选项（同一原则见 Host 侧
 * `availableContextTiers`）。
 *
 * ⚠️ **没有默认档就不渲染**：缺 `contextWindow` 时既无法标出「默认」也无法表达
 * 选中态，与其画一组全不选中的 radio，不如不画。
 */
function tierOptionsOf(model) {
  const dev = model.contextWindow;
  if (typeof dev !== 'number' || !Number.isFinite(dev) || dev <= 0) return null;
  const declared = Array.isArray(model.contextTiers) ? model.contextTiers : [];
  const valid = declared.filter(v => typeof v === 'number' && Number.isFinite(v) && v > 0);
  const tiers = [...new Set([...valid, dev])].sort((a, b) => a - b);
  if (tiers.length >= 2) return tiers;
  // 老形态兜底：只有 dev / max 两个字段（`max` 必须严格大于 `dev` 才算第二档）。
  const max = model.maxContextWindow;
  if (typeof max === 'number' && Number.isFinite(max) && max > dev) return [dev, max];
  return null;
}

/**
 * 该档位在界面上的名字。
 *
 * - 默认档恒为「默认」（它就是未设置预算时宿主用的那一档）；
 * - `maxContextWindow` 命中时叫「Max」（Trae CN 的既有文案，不要因为推广到多档
 *   就把它降级成一串裸数字）；
 * - 其余用容量缩写（`400K` / `1M`）—— 多档 provider 没有「Max 档」这个概念，
 *   最大的那一档也只是目录公布的众多窗口之一。
 */
function tierLabelOf(window, dev, max) {
  if (window === dev) return '默认';
  if (typeof max === 'number' && window === max) return 'Max';
  return formatCapacity(window);
}

/**
 * 单个模型的上下文窗口档位选择（每档一个 `Pill`，档数由 Host 数据决定）。
 *
 * ## 选中态
 *
 * `contextBudget` **精确等于**某个非默认档 → 选中它；否则（未设置预算 / 预算等于
 * 默认档 / 预算因目录漂移而失效）一律选中默认档。这与 Host 侧
 * `effectiveContextWindow` 的判据**同源**：界面上显示的选中项，就是宿主真正会用的
 * 那个窗口 —— 否则会出现「界面显示 1M、实际按 200K 压缩」这种看不见的分叉。
 *
 * ## 为什么是 Pill 而不是原生 radio
 *
 * 迁移前每档是一个原生 `<input type=radio>` + 文案。原生 radio 的选中态由浏览器
 * 绘制（`accent-color` 是唯一的调色入口），无法完全跟随 DSH 主题；`Pill` 是
 * ui-primitives 里的可选中胶囊，`active` 表达选中态、颜色全走 token。
 *
 * **语义按「单选组」重建**，不是降级成一个普通按钮组：
 * - 外层保留 `role="radiogroup"` + `aria-label`（可读名原样）；
 * - 每档一个 `Pill`，带 `role="radio"` 与 `aria-checked`，并保留 `disabled`；
 * - 点击只回调 `onSelect(model.id, window)` —— 受控语义与迁移前逐字一致
 *   （选中态只由 `contextBudget` 决定，不做本地乐观更新）。
 *
 * ## 为什么档位不在包住显示开关的 label 里
 *
 * 这个组件挂在模型行的右侧、与「显示开关」同级。迁移前若把 radio 放进**包住开关
 * 的那个 `<label>`** 里，点档位会连带激活 label 的隐式控件（那个 checkbox），
 * 一次点击同时改两件事。迁移后 `Switch` 本身是 `<button role="switch">`，隐式
 * label 关联已经不存在，但**结构照旧**：`ModelToggle` 的根节点仍是 `div`，
 * 档位与开关分列两侧。
 */
function ModelTierPicker({ model, busy, onSelect }) {
  const dev = model.contextWindow;
  const tiers = tierOptionsOf(model);
  if (tiers === null) return null;
  const budget = model.contextBudget;
  // 预算命中某个**非默认档**才算选了它；其余一切情况都是默认档。
  const selected = typeof budget === 'number' && budget !== dev && tiers.includes(budget) ? budget : dev;
  const name = model.name || model.id;
  const option = (window) => {
    const label = tierLabelOf(window, dev, model.maxContextWindow);
    const capacity = formatCapacity(window);
    // 有名档位（默认 / Max）是「名字 + 容量」，无名档位（多档 provider 的中间档）
    // 的容量本身就是它的名字，重复一遍会渲染成 `400K 400K`。
    const text = label === capacity ? capacity : `${label} ${capacity}`;
    // 精确值放悬停提示：缩写是给一眼扫过的，tooltip 是给要核对数字的人的。
    return React.createElement(Pill, {
      key: `dim-ah-tier-${model.id}-${window}`,
      active: selected === window,
      disabled: busy,
      role: 'radio',
      'aria-checked': selected === window,
      onClick: () => onSelect(model.id, window),
      className: 'dim-ah-tierOption',
    }, withHoverTitle(React.createElement('span', null, text), `${label}档 · ${window} token`));
  };
  return React.createElement('div', {
    className: 'dim-ah-modelTier',
    role: 'radiogroup',
    'aria-label': `${name} 上下文窗口档位`,
  }, ...tiers.map(option));
}

/**
 * 单个模型的开关。
 *
 * 刻意不做本地乐观更新：模型列表与黑名单都以 Host 为准（可能是远端拉取的
 * 结果），本地猜测状态容易与真实持久化结果分叉。这里等 RPC 返回后再翻状态，
 * 期间禁用开关，保证界面上看到的就是服务端已接受的。
 */
function ModelToggle({ model, busy, onToggle, tierBusy, onSelectTier }) {
  const name = model.name || model.id;
  return React.createElement('div', {
    className: 'dim-ah-modelRow',
    'data-disabled': model.disabled ? 'true' : 'false',
  },
    // 左侧「名字 + id」与右侧开关分列：迁移前它们被包在同一个 `<label>` 里
    // （用隐式关联把点击热区并起来），而隐式 label 会让**同层**的档位控件也被
    // 连带激活。`Switch` 自带 `aria-label` 可读名，不再需要 label 关联，
    // 故这里用普通 div —— 点击热区回到开关本体，档位不会再被误触。
    React.createElement('div', { className: 'dim-ah-modelMain' },
      withHoverTitle(React.createElement('span', { className: 'dim-ah-modelInfo' },
        React.createElement('strong', { className: 'dim-ah-modelName' }, name),
        React.createElement('code', { className: 'dim-ah-modelId' }, model.id)), model.id),
      React.createElement(Switch, {
        checked: !model.disabled,
        disabled: busy,
        label: `${name} 是否在模型选择中显示`,
        onChange: () => onToggle(model.id, !model.disabled),
      })),
    React.createElement(ModelTierPicker, {
      model,
      busy: tierBusy,
      onSelect: onSelectTier,
    }));
}

/**
 * 模型列表弹窗：点击「模型列表」后以 modal 形式浮出。
 *
 * 数据全部来自 `model.list` RPC —— 也就是适配器 `listModels()` 播报的同一份
 * 目录（对话框模型选择器读的正是它）。因此这里列出的模型与可选模型一一对应，
 * 不会出现「设置页有、选择器里没有」的错位。
 *
 * 用 modal 而不是内联展开：开关列表可能有几十项，内联会挤占账号区的空间，
 * 也让「账号池」与「模型可见性」两件不相关的事在视觉上混在一起。
 */
function ModelListPanel({ provider, rpcCall, onClose }) {
  const [models, setModels] = React.useState(null);
  const [phase, setPhase] = React.useState('loading');
  const [error, setError] = React.useState(null);
  // 单次开关操作的失败提示。与 `error` 分开：列表本身的读取失败要用整页
  // 错误态替换，而单次切换失败只需顶部提示、列表必须保留。
  const [toggleError, setToggleError] = React.useState(null);
  // 目录来源（C3）：'fallback' 时顶部渲染一行「兜底清单」提示 —— 用户需要知道
  // 这份列表是静态兜底（远端目录不可达），而不是该 Provider 的全部模型。
  const [catalogSource, setCatalogSource] = React.useState(null);
  // 正在提交的模型 id 集合：只禁用被点的那一行，避免整表锁死。
  const [busyIds, setBusyIds] = React.useState(() => new Set());
  // 正在提交档位的模型 id 集合。与 `busyIds` 分开：两者是同两行上的**两件独立的事**
  // （改可见性不该禁用档位选择，反之亦然）。
  const [tierBusyIds, setTierBusyIds] = React.useState(() => new Set());
  const mounted = React.useRef(true);

  const load = React.useCallback(async () => {
    setPhase('loading');
    setError(null);
    try {
      const res = await rpcCall('model.list', { provider });
      if (!mounted.current) return;
      setModels(res.models || []);
      // 目录来源（C3）：Host 只对实现了该能力的适配器（Qoder 两区）带出该字段，
      // 缺省（undefined）时保持 null —— 不给其余 provider 渲染无意义的提示行。
      setCatalogSource(res?.catalogSource || null);
      setPhase('ready');
    } catch (caught) {
      if (!mounted.current) return;
      setError(caught?.message || '无法读取模型列表');
      setPhase('error');
    }
  }, [provider, rpcCall]);

  React.useEffect(() => {
    mounted.current = true;
    void load();
    return () => { mounted.current = false; };
  }, [load]);

  // ESC 关闭由 `Modal` 自己接管（它在 open 期间监听 document 的 keydown），
  // 故这里**刻意不再**挂第二个 document 级监听：两份监听会在一次 Escape 上
  // 各关一次（幂等但多余），且「谁负责关」这件事会变成两个真相源。

  const toggleModel = async (modelId, disabled) => {
    setBusyIds(prev => new Set(prev).add(modelId));
    setToggleError(null);
    try {
      await rpcCall('model.setDisabled', { provider, modelId, disabled });
      if (!mounted.current) return;
      setModels(prev => (prev || []).map(m => (m.id === modelId ? { ...m, disabled } : m)));
    } catch (caught) {
      console.error('[account-hub] toggle model failed:', caught);
      if (!mounted.current) return;
      // 开关切换失败不能把整张表替换成错误页——用户会以为模型列表没了。
      // 保留列表，只在顶部提示这次操作失败。
      setToggleError(caught?.message || '切换模型显示状态失败');
    } finally {
      if (mounted.current) {
        setBusyIds((prev) => {
          const next = new Set(prev);
          next.delete(modelId);
          return next;
        });
      }
    }
  };

  const all = models || [];
  const hiddenCount = all.filter(m => m.disabled).length;
  const providerLabel = PROVIDERS.find(p => p.id === provider)?.label || provider;

  /**
   * 切换某个模型的上下文窗口档位。
   *
   * 成功后**本地刷新**选中态：`contextBudget` 与该行档位表的关系就是单选列的选中
   * 判据（见 ModelTierPicker）。刻意不做乐观更新 —— 与显示开关同理，档位是否被
   * 接受由 Host 校验决定（它手上有目录），本地先翻会让「编造值被拒绝」看起来像
   * 成功了。失败时把 RPC 返回的原文显示出来：那句话里带着该模型**实际可用的档位
   * 值**，是用户唯一能据以改正的信息。
   */
  const selectTier = async (modelId, window) => {
    setTierBusyIds(prev => new Set(prev).add(modelId));
    setToggleError(null);
    try {
      const res = await rpcCall('model.setContextBudget', { provider, model: modelId, window });
      if (!mounted.current) return;
      setModels(prev => (prev || []).map(m => (m.id === modelId
        ? { ...m, contextBudget: res?.contextBudget }
        : m)));
    } catch (caught) {
      console.error('[account-hub] set context budget failed:', caught);
      if (!mounted.current) return;
      setToggleError(caught?.message || '设置上下文窗口档位失败');
    } finally {
      if (mounted.current) {
        setTierBusyIds((prev) => {
          const next = new Set(prev);
          next.delete(modelId);
          return next;
        });
      }
    }
  };

  // 档位列按**数据**出现，不按 provider 名出现：只要有一行带出了档位（多档数组或
  // 老形态的 max / dev 两字段），整列就渲染 —— 数据在，列就在；数据不在（LobsterAI /
  // CodeArts 的目录只有一个窗口），ModelTierPicker 自己返回 null。
  // 判据与组件共用同一个 `tierOptionsOf`，避免「提示行说能选、行上却没有控件」。
  const tierHint = all.some(m => tierOptionsOf(m) !== null)
    ? '上下文窗口档位只切换向对话宿主声明的窗口（影响自动压缩时机），不改变发给上游的请求内容。'
    : null;

  /**
   * 弹窗本体：`Modal` 原语（遮罩 / 居中卡片 / Escape / aria 全部由它负责）。
   *
   * 迁移前这里是手写的遮罩 + 卡片（曾经的 `.dim-ah-modalOverlay`，已删；`position: fixed`
   * 自绘遮罩）。换成原语后**内容与交互流程一个字节没变**：标题、副标题、
   * 计数、两个头部按钮、三行说明、错误提示、四种主体状态（错误 / 读取中 /
   * 空 / 列表）全部照旧，只有承载它们的壳换成了设计体系的实现。
   *
   * ⚠️ 可读名仍由 `title` 撑住：`Modal` 把它同时用作 `aria-label` 与可见标题。
   * 迁移前可见标题是「模型列表」+ 副标题 provider 名，故这里 `title` 取
   * 「模型列表」，provider 名留在 `description` 之外的头部行里（原样渲染）。
   */
  return React.createElement(Modal, {
    open: true,
    onClose,
    title: '模型列表',
    closeLabel: '关闭模型列表',
    className: 'dim-ah-modal',
    contentClassName: 'dim-ah-modalBody',
  },
    React.createElement('div', { className: 'dim-ah-modalHead' },
      React.createElement('div', { className: 'dim-ah-modalTitle' },
        React.createElement('span', { className: 'dim-ah-modalSubtitle' }, providerLabel),
        phase === 'ready'
          ? React.createElement('span', { className: 'dim-ah-modelPanelCount' },
              `${all.length} 个模型${hiddenCount > 0 ? `，已隐藏 ${hiddenCount} 个` : ''}`)
          : null),
      React.createElement('div', { className: 'dim-ah-modelPanelActions' },
        React.createElement(Button, {
          variant: 'outline',
          size: 'sm',
          disabled: phase === 'loading',
          onClick: () => void load(),
        }, phase === 'loading' ? '读取中…' : '刷新'),
        React.createElement(Button, {
          variant: 'primary',
          size: 'sm',
          onClick: onClose,
        }, '完成'))),
    React.createElement('p', { className: 'dim-ah-modalHint' },
      '关闭开关后该模型不再出现在对话框的模型选择里；其余模型（含服务端新增的）默认显示。'),
    // 目录来源提示（C3）：仅当 Host 明确播报 fallback 时显示 —— 措辞与
    // 「当前为兜底清单」风格一致，说清「为什么列表这么短」与「它是可用的」。
    catalogSource === 'fallback'
      ? React.createElement('p', { className: 'dim-ah-modalHint' },
        '当前为兜底清单（远端目录不可达），仅含少量实测可用模型；远端恢复后将自动回到完整目录。')
      : null,
    tierHint
      ? React.createElement('p', { className: 'dim-ah-modalHint' }, tierHint)
      : null,
    toggleError
      ? React.createElement('div', {
          className: 'dim-ah-probeNotice',
          'data-tone': 'error',
          role: 'alert',
        }, React.createElement('div', null, toggleError))
      : null,
    phase === 'error'
      ? React.createElement('div', { className: 'dim-ah-empty' },
          React.createElement('p', null, error),
          React.createElement(Button, { variant: 'outline', size: 'sm', className: 'dim-ah-btn-stable', onClick: () => void load() }, '重新读取'))
      : phase === 'loading'
        ? React.createElement('div', { className: 'dim-ah-empty' }, '正在读取模型列表…')
        : all.length === 0
          ? React.createElement('div', { className: 'dim-ah-empty' },
              React.createElement('p', null, '该 Provider 当前没有可用的模型。'))
          : React.createElement('div', { className: 'dim-ah-modelList' },
              all.map(model => React.createElement(ModelToggle, {
                key: model.id,
                model,
                busy: busyIds.has(model.id),
                onToggle: (id, disabled) => void toggleModel(id, disabled),
                tierBusy: tierBusyIds.has(model.id),
                onSelectTier: (id, window) => void selectTier(id, window),
              }))));
}

/**
 * 消耗顺序的三档（**值与宿主 `src/account-consumption.ts` 的联合类型逐字一致**）。
 *
 * `hint` 是给用户看的一句话语义说明：三档的差别是「这次用哪个账号」，光看名字
 * （顺序 / 遍历 / 最高优先）不足以判断实际行为。
 */
const CONSUMPTION_ORDER_OPTIONS = [
  { value: 'sequential', label: '顺序', hint: '总是用排序里的第一个可用账号' },
  { value: 'round-robin', label: '遍历', hint: '每次请求轮转下一个账号，用完一轮再从头开始（默认）' },
  { value: 'highest-balance', label: '最高优先', hint: '每次请求用积分余额最高的账号；余额未知时按顺序' },
];

/** 切换粒度的两档（含义见 `docs/agents/account-hub-storage.md`）。 */
const CONSUMPTION_SWITCH_OPTIONS = [
  { value: 'per-request', label: '按请求', hint: '每一次请求都重新选号' },
  { value: 'per-turn', label: '按轮次', hint: '一轮对话内固定用同一个账号，下一轮才换（默认，上下文更连贯）' },
];

/**
 * 宿主的默认配置（与 `DEFAULT_CONSUMPTION` 同值）：拉取失败时退回它。
 *
 * ⚠️ **必须与宿主逐字一致**，且 `order` 是 `round-robin`：这份常量是
 * `consumption.get` 失败时的兜底显示值，写错会让「读不到配置」看起来像
 * 「用户选了另一档」—— 界面与实际选号行为分叉。
 */
const CONSUMPTION_DEFAULTS = { order: 'round-robin', switch: 'per-turn' };

function ConsumptionSelect({ name, label, options, value, busy, onSelect }) {
  const [open, setOpen] = React.useState(false);
  const current = options.find(option => option.value === value);
  const items = options.map(option => ({
    id: option.value,
    // 每档自己的说明仍挂在菜单项上，展开列表时逐档可见。
    label: withHoverTitle(React.createElement('span', null, option.label), option.hint),
  }));
  return React.createElement('div', { className: 'dim-ah-consumptionGroup', 'data-name': name },
    React.createElement(Menu, {
      open,
      anchor: React.createElement(Button, {
        variant: 'outline',
        size: 'sm',
        className: 'dim-ah-consumptionSelect',
        'aria-label': label,
        'aria-haspopup': 'menu',
        'aria-expanded': open,
        disabled: busy,
        icon: React.createElement(IconChevronDownOutlineRegular),
        onClick: () => setOpen(prev => !prev),
      }, current ? current.label : value),
      items,
      // 「弹层宽度 = 按钮宽度」：宿主 Menu 的列表默认是内容宽（min-width: 144px），
      // 与锚点无关，故必须给列表一个类名把它钉到 100%（见样式表）。
      listClassName: 'dim-ah-consumptionMenu',
      selectedId: value,
      onSelect: (id) => { setOpen(false); onSelect(id); },
      onClose: () => setOpen(false),
      align: 'start',
    }));
}

/**
 * 账号消耗顺序 + 切换粒度：两个**并排**的下拉。
 *
 * ## 版面
 *
 * 与账号卡片同处一列，两个下拉**各占容器一半**：宽度之和恒等于账号卡片那一排的
 * 宽度，且不随选中项文案长短漂移。由 `ProviderPanel` 放在账号卡片列表**之前** ——
 * 它与账号区同处一个容器。
 *
 * ⚠️ 界面上**刻意没有**可见的设置名、解释文案与外框：需求是「就两个下拉」。
 * 下拉与账号卡片之间也不再有任何提示段落（原先那条排序提示已删除）。设置名通过
 * `aria-label` 提供；各档说明仅在展开的菜单选项中显示。
 *
 * ## 为什么是受控组件 + 不做乐观更新
 *
 * 选中态完全由 `value`（宿主权威值）决定，改变只回调 `onChange`。这与
 * `ModelToggle` / `ModelTierPicker` 同一条取舍：写入是否被接受由宿主校验决定
 * （非法档位会被拒绝），本地先翻会让「被拒绝」看起来像成功了。
 *
 * ⚠️ 配置用 `value` **对象**传入而不是两个平铺 prop：`switch` 是 JS 保留字，
 * 平铺就要在解构处写 `{ switch: switchMode }` 这种别名，而别名一旦漏写会静默
 * 拿到 `undefined`（Studio 里表现为「粒度下拉永远停在默认档」）。放进对象里
 * 没有这个问题，也让「两个设置是一组」这件事在签名上可见。
 *
 * ⚠️ `disabled` 绑 `busy`：写入在途时禁用，避免连点产生两个并发写（它们的
 * 响应到达顺序不确定，界面会闪回旧值）。
 */
function ConsumptionSelectors({ value, busy, onChange }) {
  const order = value?.order || CONSUMPTION_DEFAULTS.order;
  const switchMode = value?.switch || CONSUMPTION_DEFAULTS.switch;
  return React.createElement('div', { className: 'dim-ah-consumption' },
    React.createElement(ConsumptionSelect, {
      name: 'order',
      label: '消耗顺序',
      options: CONSUMPTION_ORDER_OPTIONS,
      value: order,
      busy,
      onSelect: (next) => onChange({ order: next }),
    }),
    React.createElement(ConsumptionSelect, {
      name: 'switch',
      label: '切换粒度',
      options: CONSUMPTION_SWITCH_OPTIONS,
      value: switchMode,
      busy,
      onSelect: (next) => onChange({ switch: next }),
    }));
}

function ProviderPanel({ provider, rpcCall }) {
  const [accounts, setAccounts] = React.useState([]);
  const [phase, setPhase] = React.useState('loading');
  const [error, setError] = React.useState(null);
  const [creating, setCreating] = React.useState(false);
  // 面板级通知行（成功或失败）。历史上它是「重测 / 清除限额」的结果位，
  // 那两对按钮（卡片上的单账号、标题栏的供应商级）都已移除，如今只剩**登录失败**
  // 这一条写入口，但组件形状与样式保持不变（ClaimNotice 与它同形）。
  const [probeNotice, setProbeNotice] = React.useState(null);
  // 积分余额：accountId → { balance, error }。与账号列表分开加载——余额要逐
  // 账号发网络请求，不能拖慢账号列表本身的渲染。
  const [credits, setCredits] = React.useState({});
  const [creditsLoading, setCreditsLoading] = React.useState(false);
  // 各账号今日签到状态：accountId → { checkedInToday, checking }。由
  // `credits.checkinStatus`（读内存零网络）在挂载时拉取，单账号签到成功后再由
  // `checkin.perform` 响应局部更新。已签/未签判定只信宿主的 `checkedIn`，客户端
  // 不自己算今日纪元日数。
  const [checkinsByAccount, setCheckinsByAccount] = React.useState({});
  // 签到状态是否已从宿主成功拉取并落地（`loadCheckinStatus` 写出后置真）。
  // 自动补签的**前置闸**：只有先确认「哪些账号今日已签」才能决定要不要补签，
  // 拉状态失败（不置真）时不自动签到，避免在无从判断的情况下误发补签请求。
  const [checkinStatusLoaded, setCheckinStatusLoaded] = React.useState(false);
  /**
   * `loadAccounts` 是否**已结算**（成功或失败都算）。
   *
   * 自动补签的**第二个前置闸**，也是本组件里「账号就绪」的**唯一显式信号**。
   *
   * ⚠️ 不要退回「`accounts` 引用非空即就绪」：那个判据把「就绪」编码在一个数组的
   * 引用上，而账号列表有两种**再也不会变化**的结算形态 —— 读到空列表、或读取失败
   *（面板进 error 态）。两者都会让 `accounts` 永远停在 `[]`，于是「非空才动手」
   * 的守卫把**整个挂载周期**的自动补签静默吞掉：界面看起来一切正常，只是签到
   * 一声不响地没发生（真机报障「首次进账号中心没签、重进才成功」的形态）。
   *
   * 另外，本地列表为空**并不代表没有可签对象**：`checkin.perform` 不带 accountId
   * 时目标集合是**宿主**按自己的账号池算的（`performCheckin` → `pool.listAccounts`），
   * 客户端读不到列表并不妨碍这次签到发生 —— 所以「结算」而非「非空」才是正确判据。
   */
  const [accountsLoaded, setAccountsLoaded] = React.useState(false);
  /**
   * 弹窗被拦截时的**手动登录链接**（`{ url }` | null）。
   *
   * 空窗开不出来时不顶掉 DSH 页面，而是在面板内渲染一个由用户亲自点击的
   * `<a href>` —— 用户手势由浏览器直接识别，不经过任何 await。
   */
  const [manualLogin, setManualLogin] = React.useState(null);
  const mounted = React.useRef(true);
  /**
   * 最新账号列表的 ref 镜像。
   *
   * loadCredits 的失败分支需要"当前有哪些账号"，但它与 loadAccounts 并发发起，
   * 闭包里的 accounts 还是初始空数组。ref 保证读到的是最新值。
   */
  const accountsRef = React.useRef([]);
  // 签到是否进行中（自动补签与手动「一键签到」共用）：用 ref 镜像 claiming，
  // 让挂载 effect 里的自动补签能读到**实时** busy 值（闭包里的 claiming 在挂载
  // 时刻恒为初始 false），避免补签与用户刚点的手动签到并发各发一次 checkin.perform。
  const claimingRef = React.useRef(false);
  // 本面板是否已执行过自动补签：每次面板挂载只补一次（对应需求「每次进入 Hub」）。
  // React.StrictMode 在 dev 会双执行挂载 effect，ref 挡住第二发。
  const autoCheckinRanRef = React.useRef(false);
  /**
   * 消耗顺序 / 切换粒度（宿主权威值）。
   *
   * 初始为宿主的默认档（顺序 + 按轮次）—— 与 `consumption.get` 未返回时的兜底
   * 同一个值。挂载后由 RPC 覆盖。**刻意不从本地存储猜**：配置存在宿主的 storage
   * 域里，客户端猜错会让界面显示一个与真实选号行为不符的档位。
   */
  const [consumption, setConsumption] = React.useState(CONSUMPTION_DEFAULTS);
  // 消耗配置写入在途（禁用两个选择器，防连点产生并发写）。
  const [consumptionBusy, setConsumptionBusy] = React.useState(false);
  /**
   * 拖拽排序状态：正在拖的账号 id、当前悬停的目标账号 id、落点方向。
   *
   * 三者都只用于**视觉反馈**（源卡片淡出、目标卡片显示插入线），真正的顺序
   * 变更在 drop 时才提交给宿主。状态刻意放在 `ProviderPanel` 内而不是卡片里：
   * 只有面板知道整个列表的顺序，且**切换 provider 时面板整体重挂载**
   * （`AccountHubPage` 的 key 含 version），状态随之清空 —— 不会出现「换了
   * provider 还带着上一个面板的 draggingId」这种跨面板串味。
   */
  const [draggingId, setDraggingId] = React.useState(null);
  const [dropTargetId, setDropTargetId] = React.useState(null);
  // 落点方向：'before' | 'after'。由指针落在目标卡片的上半/下半决定，
  // 让「往下拖一格」与「往上拖一格」都能生效（详见 account-order.js）。
  const [dropPosition, setDropPosition] = React.useState('before');
  // 顺序提交在途：期间禁用拖拽，避免两次提交互相覆盖。
  const [reordering, setReordering] = React.useState(false);
  // 顺序提交失败的提示（如宿主回「列表已变化，请刷新」）。
  const [reorderError, setReorderError] = React.useState(null);
  /**
   * 待确认的删除操作（对应一个弹窗）。
   *
   * 迁移前它是原生 `confirm()`：同步阻塞、由浏览器自绘、样式不进主题体系。
   * 改为 `RiskConfirmation` 后「确认」这件事必须先变成一个**状态**（弹窗要渲染在
   * 树里），故这里多两个 state。它们是纯展示层状态，不参与任何业务判定：
   * - `pendingDelete`：待删除的账号 id（勾选 acknowledge 后才执行）；
   * - `deleteAcknowledged`：上面那枚勾选闸的当前值。
   */
  const [pendingDelete, setPendingDelete] = React.useState(null);
  const [deleteAcknowledged, setDeleteAcknowledged] = React.useState(false);

  const loadAccounts = React.useCallback(async () => {
    setPhase('loading');
    setError(null);
    try {
      // 这里**发的是面板 id**，不是它背后的账号池键。
      // 「面板 id → 池键」的映射收敛在宿主（`src/account-hub-rpc.ts` 的
      // `poolProviderFor()`）：客户端若也映射一次，
      // 宿主那几个按池过滤的分支就必须跟着改，同一件事写两遍。
      // 客户端只管把面板 id 原样送出去。
      const res = await rpcCall('account.list', { provider });
      if (!mounted.current) return;
      const list = res.accounts || [];
      accountsRef.current = list;
      setAccounts(list);
      // 结算信号：**成功也置真**（哪怕列表为空）—— 自动补签的触发由它驱动，
      // 若只在非空时置真，「读到空列表」就会让补签永不触发（见 accountsLoaded）。
      setAccountsLoaded(true);
      setPhase('ready');
    } catch (caught) {
      if (!mounted.current) return;
      setError(caught?.message || '无法读取账号列表');
      setPhase('error');
      // ⚠️ **失败同样算结算**：这一次账号列表没读到，但「等账号就绪」这件事已经
      // 有了结论 —— 继续等下去不会再来一次（本函数不会自动重试）。自动补签不该
      // 因此静默断流：目标集合由宿主掌握，客户端读不到列表不影响那一发。
      // 失败路径不置真的话，用户看到的就是「面板报错 + 签到一声不响地没发生」。
      setAccountsLoaded(true);
    }
  }, [provider, rpcCall]);

  /**
   * 本 provider 是否支持积分余额查询。
   *
   * 判定依据是 `./credits-capabilities.js` 的能力矩阵（唯一真相源），
   * 而不是散落在 UI 里的 provider 字面量比较。
   *
   * 这里必须在**发起请求之前**判掉：既不调用 RPC，也不渲染「积分」行与
   * 「刷新积分」按钮——否则卡片会永远停在「查询失败」，控制台每次都留报错。
   * 矩阵**默认关闭**（未登记者两项全无），故将来新增 provider 忘登记时，
   * 最坏结果是暂时看不到积分，而不是每次开面板都发一个必然失败的请求。
   *
   * ⚠️ 历史缺陷（能力矩阵存在的理由）：早期 CodeArts 两项能力皆无，客户端却在
   * 面板挂载时对所有 provider 无条件调用 `credits.balances`，于是每打开一次
   * CodeArts 面板都在控制台留一条必然失败的报错、并把账号卡片渲染成
   * 「查询失败」。CodeArts 后来已接入真实实现（`src/codearts-credits.ts`，
   * 两项能力由全假变为全真），**门控机制本身不变**。
   */
  const canLoadCredits = supportsCreditBalance(provider);
  // 只有支持签到能力的 provider（当前六个面板：Buddy CN / LobsterAI / Trae CN /
  // CodeArts / Qoder 两区）渲染领取按钮；Buddy 国际版后端无签到接口，不在其中。
  const supportsCredits = supportsDailyCheckin(provider);
  /**
   * 本面板的**显示名**（`PROVIDERS` 条目的 `label`，找不到时回退 `provider` id）。
   *
   * ⚠️ 这是**本函数作用域内**的绑定，不是随手一个 `label` —— 2026-09-21 的白屏
   * 报障正是因为某处把显示名写成了裸 `label`，而那个标识符在该位置**没有任何
   * 绑定**（它只作为局部变量存在于 `formatClaimFailureLine`，以及 `PROVIDERS`
   * 条目的字段名里），于是抛的是 `ReferenceError` 而不是拿到 `undefined`。
   *
   * 那个错法的恶劣之处在于**三重闸门全都看不见**：`plugin-src/` 不在
   * `tsconfig.json` 的 include 里（tsc 不查）；`ProviderPanel` 用了 hooks、
   * react 不在依赖里，既有单测只能做源码切片与正则断言（从不真的渲染它）；
   * 而 `build:client` 的冒烟只求值 bundle **顶层**，函数体从未被调用。
   * 于是它一路活到真机：那个对象字面量在条件为假时不求值 ⇒ 页面正常；
   * 用户点「登录账号」（旧文案「+ 新建账号」）⇒ 重渲染时求值 ⇒ `ReferenceError` 从 render 抛出 ⇒
   * 整棵 React 树（无错误边界）卸载 ⇒ **Hub 整页空白**。
   *
   * 故这里统一用 `providerLabel` 这一个绑定（与 `ModelListPanel` 的写法一致），
   * 面板标题与领取按钮 title 都由它来 —— 再写一次裸 `label` 就会是同一个缺陷。
   * `tests/unit/qoder-hub-blank-screen.spec.ts` 真的渲染面板并派发点击，
   * 钉死这一类自由变量。
   */
  const providerLabel = PROVIDERS.find(p => p.id === provider)?.label || provider;

  /**
   * 拉取本页全部账号的积分余额。
   *
   * 单独一个请求、单独的 loading 状态：余额查询涉及逐账号的网络往返，可能
   * 慢或失败；它绝不能影响账号列表的可用性——查不到余额时卡片显示原因，
   * 而不是让整个面板变成错误页。
   *
   * **不支持的 provider 直接返回**：不支持的 provider（CodeArts）连请求都不发。
   * 这是刻意放在函数内部而不是只靠调用点判断——`claimCredits` / 「刷新积分」
   * 按钮等多个入口都调它，门控收在这里才不会被将来新增的调用点绕过。
   */
  const loadCredits = React.useCallback(async () => {
    if (!canLoadCredits) return;
    setCreditsLoading(true);
    try {
      const res = await rpcCall('credits.balances', { provider });
      if (!mounted.current) return;
      const next = {};
      for (const item of res.accounts || []) {
        next[item.accountId] = { balance: item.balance, error: item.error };
      }
      setCredits(next);
    } catch (caught) {
      console.error('[account-hub] load credits failed:', caught);
      if (!mounted.current) return;
      // 整批失败（如 provider 不支持、RPC 未注册）：给当前每个账号都留下失败
      // 原因，避免卡片永远停在"读取中"。
      //
      // 用 accountsRef 而不是闭包里的 accounts：本函数与 loadAccounts 在挂载时
      // 并发发起，此刻闭包捕获的 accounts 仍是初始空数组，会导致一个账号都
      // 标记不上。ref 始终指向最新值。
      const snapshot = accountsRef.current;
      setCredits(prev => {
        const next = { ...prev };
        for (const account of snapshot) {
          next[account.id] = { balance: null, error: caught?.message || '积分查询失败' };
        }
        return next;
      });
    } finally {
      if (mounted.current) setCreditsLoading(false);
    }
  }, [provider, rpcCall, canLoadCredits]);

  /**
   * 拉取本 provider 各账号的今日签到状态（`credits.checkinStatus`）。
   *
   * 纯内存读、不发任何网络请求。结果映射为 `accountId → { checkedInToday }`，
   * 供头部「一键签到」的「全部已签」与每账号「签到」按钮的「已签」态使用。
   *
   * 只在支持签到的 provider 上调用（`supportsCredits` 门控，与按钮渲染同源），
   * 否则宿主对无签到能力 provider 返回空表、拉它也是空转。
   *
   * **用 accountsRef 而非闭包里的 accounts**：本函数与 loadAccounts 在挂载时并发
   * 发起（见下方 useEffect），此刻闭包捕获的 accounts 仍是初始空数组——仅凭空数组
   * 提前 `setCheckinsByAccount({})` 会把稍后来自宿主的状态整个清掉。ref 始终指向
   * 最新值，只有当它非空（账号列表已就绪）才用宿主返回的结果覆盖。
   */
  const loadCheckinStatus = React.useCallback(async () => {
    if (!supportsCredits) return;
    try {
      const res = await rpcCall('credits.checkinStatus', { provider });
      if (!mounted.current) return;
      // 用 accountsRef 的当前快照比对：宿主按 today 算好 checkedIn，这里只看
      // 「账号真的在列表里」就采纳；账号为空时（列表还没就绪）不写，避免清空。
      if (accountsRef.current.length > 0 || res.checkedIn) {
        const next = {};
        for (const account of accountsRef.current) {
          next[account.id] = {
            checkedInToday: Boolean(res.checkedIn?.[account.id]),
            // 宿主侧的**旁路抑制态**（`undetermined` 后的窗口内退避，见
            // `src/account-hub-rpc.ts` 的 `undeterminedSuppressUntil`）。
            // ⚠️ 它与 `checkedInToday` 是**正交**的两件事，合并任何一个方向都会
            // 制造缺陷：并进 `checkedInToday` ⇒ 被抑制的账号显示「已签」+ 按钮
            // 禁用，而它**可能一分没领**（正是「假签到」的界面形态）；不带上它
            // ⇒ 下面的自动补签会把「未签」当成「该补一发」并再发一次，宿主刚堵住
            // 的空转循环从客户端这条路原样复活。
            // 旧宿主不返回该字段 ⇒ `undefined` ⇒ `Boolean(undefined) === false`
            // ⇒ 行为退回改动前（多发一发幂等查询），不会读错任何东西。
            suppressed: Boolean(res.suppressed?.[account.id]),
          };
        }
        setCheckinsByAccount(next);
      }
      // 成功即置「签到状态已落地」——即使此刻 accountsRef 尚空（与 loadAccounts
      // 并发竞态），也标记状态已可用，让自动补签的触发 effect 等账号列表就绪后
      // 再动手；只有拉取失败才不置真，据此跳过自动补签。
      if (mounted.current) setCheckinStatusLoaded(true);
    } catch (caught) {
      // 签到状态是可选的增强信息：拉不到不该让面板崩溃或报错，静默即可；
      // 头部按钮会按「全部未签」推出（allCheckedIn 恒 false），单签按钮正常可点。
      console.warn('[account-hub] load checkin status failed:', caught);
    }
  }, [provider, rpcCall, supportsCredits]);

  /**
   * 拉取本 provider 的消耗顺序 / 切换粒度（纯内存读、零网络）。
   *
   * 失败**静默**：选择器退回默认档而不是把面板变成错误页 —— 一份读不到的配置
   * 不该让整个账号管理界面不可用（与 `loadCheckinStatus` 同一条取舍）。
   * 退默认档是安全的：`CONSUMPTION_DEFAULTS` 与宿主 `DEFAULT_CONSUMPTION` 同值，
   * 因此界面显示的就是宿主此刻实际生效的档位。
   */
  const loadConsumption = React.useCallback(async () => {
    try {
      const res = await rpcCall('consumption.get', { provider });
      if (!mounted.current) return;
      setConsumption({
        order: res?.consumption?.order || CONSUMPTION_DEFAULTS.order,
        switch: res?.consumption?.switch || CONSUMPTION_DEFAULTS.switch,
      });
    } catch (caught) {
      console.warn('[account-hub] load consumption setting failed:', caught);
    }
  }, [provider, rpcCall]);

  /**
   * 写回消耗配置（**部分更新**：只发被点的那一个字段）。
   *
   * 成功后用**宿主返回的**配置覆盖本地状态（而不是用自己刚才点的值）：宿主的
   * 响应是写入后的权威值，本地猜可能与它不一致（例如值被归一化成默认档）。
   * 失败时只记控制台 + 保留原选中态 —— 与模型开关同理，不做乐观更新。
   */
  const updateConsumption = async (patch) => {
    setConsumptionBusy(true);
    try {
      const res = await rpcCall('consumption.set', { provider, ...patch });
      if (!mounted.current) return;
      setConsumption({
        order: res?.consumption?.order || CONSUMPTION_DEFAULTS.order,
        switch: res?.consumption?.switch || CONSUMPTION_DEFAULTS.switch,
      });
    } catch (caught) {
      console.error('[account-hub] update consumption setting failed:', caught);
    } finally {
      if (mounted.current) setConsumptionBusy(false);
    }
  };

  /**
   * 把账号列表重排为 `orderedIds` 并持久化。
   *
   * **乐观更新**：先本地改顺序（拖拽手感必须即时），再提交宿主；失败则回滚并
   * 提示。拖拽若等一个网络往返才动，会明显发滞。
   *
   * 顺序不是纯 UI 状态：它就是 `AccountPool.getAvailableAccount` 的候选优先级，
   * 即自动选号与限流换号的实际取号顺序（宿主侧 `AccountPool.reorderAccounts`，
   * 载荷要求 orderedIds 必须是该 provider 全部 id 的一个**排列**）。
   */
  const commitOrder = async (orderedIds) => {
    const snapshot = accountsRef.current;
    // 顺序没变就什么都不做：把 `a` 拖到 `b` 的**上半区**会算出与原顺序相同的
    // 数组（`orderAfterDrop` 对该落点返回等价排列，见 account-order.js 的说明），
    // 那是一次「拖回原位」。宿主虽然对无变化的 replace 也不写盘
    // （`AccountPool.reorderAccounts` 的注释），但没有必要为此多打一次网络往返
    // ——拖拽落回原位是很常见的动作。
    const unchanged = snapshot.length === orderedIds.length
      && snapshot.every((account, index) => account.id === orderedIds[index]);
    if (unchanged) return;
    const byId = new Map(snapshot.map((account) => [account.id, account]));
    const next = orderedIds.map((id) => byId.get(id)).filter(Boolean);
    // 理论不可达：id 集合来自本列表。真发生了也绝不发请求 —— 半截列表会被
    // 宿主判 bad-request，或者更糟：被当成合法排列写进池子（丢账号）。
    if (next.length !== snapshot.length) return;
    accountsRef.current = next;
    setAccounts(next);
    setReordering(true);
    setReorderError(null);
    try {
      await rpcCall('account.reorder', { provider, orderedIds });
    } catch (caught) {
      console.error('[account-hub] reorder failed:', caught);
      if (!mounted.current) return;
      // 回滚：宿主没接受这个顺序，界面不能停在「看起来已生效」的状态 ——
      // 那会让用户以为优先级已经改了，而实际取号顺序还是旧的。
      accountsRef.current = snapshot;
      setAccounts(snapshot);
      setReorderError(caught?.message || '顺序保存失败');
    } finally {
      if (mounted.current) setReordering(false);
    }
  };

  /**
   * 计算把 `sourceId` 放到 `targetId` 前/后的新顺序。
   *
   * 实际逻辑在 `./account-order.js`（纯函数，可单测）：这里只取当前列表的 id
   * 序列并转交。`position` 由指针落在目标卡片的上半/下半决定 —— 只支持
   * 「插入到之前」会让「往下拖一格」变成空操作（见该模块的说明）。
   */
  const computeDropOrder = (sourceId, targetId, position) =>
    orderAfterDrop(accountsRef.current.map((account) => account.id), sourceId, targetId, position);

  /** 构造某张卡片的拖拽属性（不启用拖拽时返回 `{ enabled: false }`）。 */
  const dragPropsFor = (account, index) => {
    // 只有一个账号时排序无意义，直接不启用（避免出现无法落点的拖拽）。
    if (accounts.length < 2) return { enabled: false };
    return {
      enabled: true,
      order: index,
      isDragging: draggingId === account.id,
      // 目标高亮只在「确实拖着一张别的卡片」时出现 —— 否则鼠标划过每张卡片
      // 都会亮插入线（dragover 之外的悬停不该有落点提示）。
      isDropTarget: dropTargetId === account.id && draggingId !== null && draggingId !== account.id,
      dropPosition,
      onDragStart: (event) => {
        setDraggingId(account.id);
        setReorderError(null);
        // 必须设置 dataTransfer，否则 Firefox 根本不启动拖拽。
        try { event.dataTransfer.setData('text/plain', account.id); } catch { /* 忽略 */ }
        if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move';
      },
      onDragEnd: () => {
        // 无论落点是否有效（含拖到面板外取消），临时状态都必须清干净。
        setDraggingId(null);
        setDropTargetId(null);
      },
      onDragOver: (event) => {
        if (draggingId === null || draggingId === account.id) return;
        // 必须 preventDefault，否则浏览器不把这里当作可放置区域。
        event.preventDefault();
        if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
        if (dropTargetId !== account.id) setDropTargetId(account.id);
        // 按指针在卡片内的纵向位置决定插到前面还是后面。
        const rect = event.currentTarget?.getBoundingClientRect?.();
        const position = dropPositionFromPointer(event.clientY, rect);
        if (position !== dropPosition) setDropPosition(position);
      },
      onDrop: (event) => {
        event.preventDefault();
        const sourceId = draggingId;
        // 先清视觉状态再提交：提交是异步的，拖拽反馈不该跟着网络往返走。
        setDraggingId(null);
        setDropTargetId(null);
        if (sourceId === null || sourceId === account.id) return;
        const next = computeDropOrder(sourceId, account.id, dropPosition);
        // null = 源与目标同一张卡（或 id 不在列表里）：不发请求、不改顺序。
        if (next !== null) void commitOrder(next);
      },
    };
  };

  React.useEffect(() => {
    mounted.current = true;
    void loadAccounts();
    // 消耗配置与账号列表并发拉取：它是零网络的内存读（与签到状态同理），
    // 不必等账号列表就绪。
    void loadConsumption();
    // 只有支持余额查询的 provider 才在挂载时拉积分；CodeArts 不会走到这里
    // （loadCredits 内部也有一道门控，这里提前判掉是为了连 loading 状态都不翻）。
    if (canLoadCredits) void loadCredits();
    // 只要支持签到就拉一次签到状态：可以是最新账号列表就绪后，但这里与
    // loadAccounts 并发也无妨——loadCheckinStatus 内部用 accountsRef 防并发读到
    // 空数组（上面注释）。每次进入 Hub 页面都会触发本 effect → 每次进入都检测。
    void loadCheckinStatus();
    return () => { mounted.current = false; };
    // loadCredits 依赖 accounts，但这里只想在挂载/provider 变化时各跑一次；
    // 账号刷新后由操作方显式再调 loadCredits（见 claimCredits）。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [provider]);

  // 自动补签触发点：本面板挂载后，**两个完成信号都就绪**（签到状态已落地 +
  // 账号列表已结算）就对未签账号自动补一次 `checkin.perform`。
  //
  // ⚠️ 依赖刻意**只有这两个完成信号**，不含 `accounts`：把「账号就绪」编码成
  // 「某个数组的引用变化」正是本次要修的缺陷 —— 列表结算为「空」或「读取失败」
  // 时那个引用再也不会变，触发条件永远不成立，补签被静默吞掉（见 accountsLoaded）。
  // 两个信号各自只置真一次（`loadCheckinStatus` / `loadAccounts` 各一处），故本
  // effect 至多再触发一次，`autoCheckinRanRef` 仍然保证整个挂载周期只自动签一次。
  React.useEffect(() => {
    if (checkinStatusLoaded && accountsLoaded) void autoCheckinOnEntry();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [checkinStatusLoaded, accountsLoaded]);

  // 积分领取状态：claiming 用于禁用按钮，claimNotice 展示上一次领取的结果摘要。
  const [claiming, setClaiming] = React.useState(false);
  const [claimNotice, setClaimNotice] = React.useState(null);
  // 「模型列表」：控制模型列表面板的展开状态。关闭时不挂载面板，避免
  // 每次进入面板都白白发一次 model.list 请求。
  const [showModels, setShowModels] = React.useState(false);

  /**
   * 一键领取当前 provider 下全部已启用账号的每日签到积分。
   *
   * 后端逐个账号顺序处理，单个账号失败不会中断整批，因此这里通常正常返回，
   * 由 summary 各计数决定提示文案与色调。
   *
   * **不支持的 provider 直接返回**：守卫与按钮渲染同源（`supportsCredits`），
   * 放在函数内是为了将来若从别处调用（如快捷键、批量入口）也不会打到
   * `unsupported provider` 上——按钮不渲染只是 UI 便利，不是安全边界。
   */
  const claimCredits = async () => {
    if (!supportsCredits) return;
    if (claimingRef.current) return;
    claimingRef.current = true;
    setClaiming(true);
    setClaimNotice(null);
    try {
      // 头部「一键签到」走 `checkin.perform`（不带 accountId = 该 provider 全量）。
      // 响应与 `credits.claimAll` **同构**（results[].nickname + 完整 ClaimOutcome
      // 对象），故下方的摘要/失败明细消费代码（buildClaimNotice / claimFailureLines
      // / formatClaimFailureLine）一字不改即可复用。
      const res = await rpcCall('checkin.perform', { provider });
      // 宿主回 `busy`：另一路签到在跑，本次**一个 claim 都没发**。既不是成功也不能
      // 报成失败（进度正在别处推进），故走同一句「已有签到正在进行」提示并直接收尾
      // —— 空 summary 喂给 buildClaimNotice 会显示成「没有可领取的账号」，那是
      // 把「没跑」谎报成「跑了但没有账号」，正是本次要消灭的形态。
      if (res?.busy) {
        if (mounted.current) setClaimNotice(CHECKIN_BUSY_NOTICE);
        return;
      }
      // 摘要与失败明细一起交给 ClaimNotice（含每个失败账号的服务端 code +
      // message —— 早期实现只解构 summary，把用户判断原因的唯一依据整块丢了）。
      const notice = buildClaimNotice(res);
      if (!mounted.current) return;
      setClaimNotice(notice);
      await loadAccounts();
      // 领取会改变余额，顺带刷新一次，免得卡片还显示领取前的数字
      await loadCredits();
      // 一键领取后各账号今日状态已变，刷新签到状态让头部按钮翻成「全部已签」。
      await loadCheckinStatus();
    } catch (caught) {
      console.error('[account-hub] claim credits failed:', caught);
      if (!mounted.current) return;
      setClaimNotice({ tone: 'error', text: caught?.message || '领取积分失败' });
    } finally {
      claimingRef.current = false;
      if (mounted.current) setClaiming(false);
    }
  };

  /**
   * 本 provider 全部账号今日是否都已签到。
   *
   * 由 `credits.checkinStatus` 带回的数据派生：只要列表非空且每个账号
   * `checkedInToday` 都为 true 即为「全部已签」。头部「一键签到」按钮据此
   * 显示「全部已签」并禁用。拉取失败（checkinsByAccount 缺失条目）时该账号
   * 视为未签 → allCheckedIn 恒 false，不会误杀用户的签到入口。
   */
  const allCheckedIn = supportsCredits
    && accounts.length > 0
    && accounts.every(a => checkinsByAccount[a.id]?.checkedInToday === true);

  /**
   * 自动补签（需求：每次进入 Hub 页面时，未签账号要自动签到）。
   *
   * 语义对齐需求原文 —— 已签/签到成功都算已签：以 `checkinsByAccount`（由宿主的
   * `checkedIn` 判定，客户端不算今日纪元）为准，存在任一账号
   * `checkedInToday !== true` 就**自动补一次** `checkin.perform({ provider })`
   *（全量，不带 accountId，覆盖全部账号）。已签账号由宿主幂等归
   * `already-claimed`，无害。**只有面板挂载时才触发一次**（见挂载 effect），
   * 进入 Hub 页即该 provider 面板挂载时执行。
   *
   * ## 就绪判据是「结算」而不是「非空」（2026-09-24 修复）
   *
   * 本函数原先在 `accounts.length === 0` 时直接 `return`（不置 ran，指望账号列表
   * 就绪后再触发一次）。那个指望只在列表**从空变非空**时成立 —— 而列表还有两种
   * 终态：读到空数组、读取失败（面板进 error 态）。两者都不会再来一次状态更新，
   * 于是本次挂载的自动补签被**静默吞掉**：界面正常、签到一声不响地没发生。
   * 现在等的是 `accountsLoaded`（`loadAccounts` 的结算信号，成败都置真），且本地
   * 列表为空**不构成**跳过理由 —— `checkin.perform` 不带 accountId 时目标集合由
   * **宿主**按自己的账号池决定，客户端读不到列表并不妨碍那一发。
   *
   * 反之，若宿主回 `busy`（另一路签到在跑），那一路签的是同一批账号，故不重试、
   * 不打扰用户，只在控制台留一行「被挡」—— 静默的「跑了」与静默的「没跑」必须
   * 在日志层可区分，否则下一次排查又要从零开始。
   *
   * 为什么是「进入页面自动补」而不是所有调用点：签到状态（`checkinStatus`）本来
   * 就是零网络纯内存读，这里补签也只在成本可忽略时发生；手动「一键签到」已有
   * `claimCredits`，两者共用 `claimingRef` 互斥，不会重复并发各发一次。
   *
   * 失败**静默**：自动补签不得弹打断性通知（用户只是进页面，不该被失败打断），
   * 也不得把页面搞坏 —— catch 后仅刷新签到状态，让按钮态回到「未签」由用户
   * 决定是否手动补。与手动的 `claimCredits`（会弹 claimNotice）刻意分开。
   */
  const autoCheckinOnEntry = async () => {
    if (!supportsCredits) return;
    if (autoCheckinRanRef.current) return;
    // 账号列表尚未**结算**（与 loadCheckinStatus 并发时状态可能先到）：
    // 什么都不做，**也不置 ran** —— `accountsLoaded` 置真后的那次 effect 会再进来
    // 补判一次。判据是「已结算」而不是「引用非空」：空列表 / 读取失败同样是结算，
    // 且本地列表读不到**不影响**这次签到（目标集合由宿主按自己的账号池决定）。
    if (!accountsLoaded) return;
    // 已全部签过、或全部处于**宿主旁路抑制期**，就无需自动补签 —— 两者都是
    // 「此刻不该再发这一发」。
    //
    // `suppressed` 是 `undetermined` 之后的窗口内退避态（宿主侧
    // `src/account-hub-rpc.ts` 的 `undeterminedSuppressUntil`）。⚠️ 它**不是**
    // 「已签」：那些账号照旧显示「签到」、按钮可点（`allCheckedIn` **不读**它，
    // 见下）。但自动补签必须跳过 —— 否则「进一次面板补一发」会从客户端这条路
    // 原样复活宿主刚堵住的空转循环，而这一发的结局注定还是 `undetermined`。
    //
    // ⚠️ `accounts.length > 0` 这一半不可省：`[].every()` **恒为 true**，只留
    // `every` 会把「本地没有可判对象」（列表结算为空）误判成「已全部签过」——
    // 缺陷只是从上面那道守卫换到这个位置，形态一模一样（静默不发）。
    if (accounts.length > 0 && accounts.every(a => {
      const state = checkinsByAccount[a.id];
      return state?.checkedInToday === true || state?.suppressed === true;
    })) return;
    // 走到这里才算真正发起过判定/补签，标记本面板只做这一次。
    autoCheckinRanRef.current = true;
    // 已有手动签到在跑（claimed 或单片 checkinAccount 都置 claiming），别并发。
    if (claimingRef.current) return;
    claimingRef.current = true;
    if (mounted.current) setClaiming(true);
    try {
      const res = await rpcCall('checkin.perform', { provider });
      // 宿主回 `busy`：**另一路签到正在跑**（4h / 启动 sweep，或本面板另一发），
      // 本次**没有发过任何 claim**。它签的是同一批账号，故无需重试、也不必打断
      // 用户（自动补签的失败一律静默）—— 但要如实记录「被挡」而不是当成已处理：
      // 静默的「跑了」与静默的「没跑」在日志层必须可区分。
      if (res?.busy) {
        console.warn('[account-hub] auto checkin skipped: another check-in is already running');
      }
    } catch (caught) {
      // 自动补签失败：静默，仅记录，不弹 claimNotice、不破坏页面。
      console.error('[account-hub] auto checkin failed:', caught);
    } finally {
      claimingRef.current = false;
      if (!mounted.current) return;
      setClaiming(false);
      // 无论成功失败都重拉一次签到状态，让按钮态反映真实结果；成功时头部翻成
      // 「全部已签」，失败时保留「一键签到」由用户决定是否手动补。
      try { await loadCheckinStatus(); } catch { /* 状态刷新失败也静默 */ }
    }
  };

  /**
   * 单账号签到（「签到」单片按钮）。
   *
   * 调 `checkin.perform` 携带 accountId；响应里的 `checkedInToday` 仅作参考，
   * 关键是用 `results[].outcome` 判定后续状态。**已签或签到成功都算成功**（宿主
   * 对服务端 already-claimed 也已写今日），失败/未开启/暂不可签都不回写为「已签」，
   * 下次进入/触发重试。成功后局部更新该账号状态，并联动头部按钮（若全签则变
   * 「全部已签」禁用）。
   *
   * ## 四种 outcome 都要有反馈（2026-09-23 修复）
   *
   * `checkin.perform` 的响应与 `credits.claimAll` **同构**（`results[]` +
   * `summary`），故 {@link buildClaimNotice} 可以直接吃它 —— 本次改动的核心就是
   * **把 outcome 交给那个既有的通知构造器**。此前这里只用了 `outcome.kind`
   * 更新状态，一个字符都不弹给用户：单账号签约**成败全无声**，点了按钮像没反应。
   *
   * 反馈分档（与 {@link buildClaimNotice} 一致，本函数不另造一套文案）：
   * - `claimed` → 「1 个账号领取成功（+N 积分）」；
   * - `already-claimed` → 「1 个今日已领取」；
   * - `unavailable` → 「1 个暂不可签」+ 明细行「…（服务端此刻暂不可签，稍后自动
   *   重试）（code 9074）」——**不**报成失败（那会让用户去排查凭据/设备，
   *   而正确动作是等宿主 4h sweep 自动重试）；
   * - `failed` → warn 色调 + 明细行（服务端原文 + code + logid）。
   *
   * ⚠️ 与自动补签（{@link autoCheckinOnEntry}）**刻意不同**：那是用户进页面时
   * 被动触发的，失败必须静默；这里是用户**主动点的按钮**，无声才是缺陷。
   *
   * 注意：单片签到也会把 `claimingRef` 置真（用于与自动补签互斥），但只禁用它
   * 自己的按钮（`checkingThisAccount`）、不置面板级 `claiming`（那只归头部
   * 「一键签到」与自动补签共用）。
   */
  const checkinAccount = async (accountId) => {
    if (!supportsCredits) return;
    // 互斥时**不再静默 return**：那种「点了没反应」正是本次要修的缺陷之一。
    // 正常路径下按钮此时已被 disabled（`claiming` 进了 disabled 条件），
    // 故这里只是键盘/程序化调用等旁路的兜底 —— 给一句话，而不是装作没发生。
    if (claimingRef.current) {
      setClaimNotice(CHECKIN_BUSY_NOTICE);
      return;
    }
    claimingRef.current = true;
    setCheckinsByAccount(prev => ({ ...prev, [accountId]: { checkedInToday: false, checking: true } }));
    try {
      const res = await rpcCall('checkin.perform', { provider, accountId });
      if (!mounted.current) return;
      // 宿主回 `busy`：另一路签到在跑，本账号这一发**没有发过任何 claim**。
      // 必须与「跑了但结果是 unavailable/failed」分开：那时服务端已经表过态，
      // 而这里什么都没发生。状态回到未签（不写「已签」），给同一句提示 ——
      // 用户该做的动作是稍候，而不是去排查凭据。
      if (res?.busy) {
        setCheckinsByAccount(prev => ({ ...prev, [accountId]: { checkedInToday: false, checking: false } }));
        setClaimNotice(CHECKIN_BUSY_NOTICE);
        return;
      }
      const outcome = res?.results?.[0]?.outcome;
      // ⚠️ **只有 claimed / already-claimed 算「已签」**（与宿主写状态的白名单
      // 同源，见 `src/account-hub-rpc.ts` 的 `performCheckinOnTargets`）。
      // `undetermined`（Qoder 空活动列表）**不算** —— 把它画成「已签」正是
      // 「qoder 假签到」的界面形态：用户看到已签，而它可能一分没领，且按钮被
      // 永久禁用、再也点不动。后端 4h sweep 会自动重试，届时才可能变成已领。
      const done = outcome?.kind === 'claimed' || outcome?.kind === 'already-claimed';
      setCheckinsByAccount(prev => ({ ...prev, [accountId]: { checkedInToday: done, checking: false } }));
      // 五种 outcome 的反馈统一走既有构造器（响应同构，直接喂）。
      // `unavailable` / `abnormal` / `undetermined` 在这里 `done` 均为 false ⇒
      // 状态不写、按钮回到「签到」，用户可再手试，后台 4h sweep 也会自动重试
      // （不新造三态状态机）。
      // `res.summary` 是 buildClaimNotice 的必需输入（它刻意不做兜底）：响应当前
      // 必然带它，真缺了就跳过通知而不是让异常冒到下面那个 catch 里去 ——
      // 那会把一次**成功**的签到报成「签到失败」。
      if (outcome !== undefined && res?.summary !== undefined) setClaimNotice(buildClaimNotice(res));
      if (canLoadCredits) void loadCredits();
    } catch (caught) {
      console.error('[account-hub] checkin failed:', caught);
      if (!mounted.current) return;
      setCheckinsByAccount(prev => ({ ...prev, [accountId]: { checkedInToday: false, checking: false } }));
      setClaimNotice({ tone: 'error', text: caught?.message || '签到失败', details: [] });
    } finally {
      claimingRef.current = false;
    }
  };

  const createAccount = async () => {
    setCreating(true);
    // 弹窗被拦截时展示的手动登录链接（{ url } | null）。渲染在面板内，
    // **绝不**用 location.href 顶掉 DSH 页面。
    setManualLogin(null);
    /**
     * 手势内先开的空窗。
     *
     * 必须在**任何 await 之前**打开：`window.open` 只有在用户手势的同步调用栈里
     * 才不会被拦截。宿主侧虽然已把 `account.create` 改成秒回，但客户端不该依赖
     * 「RPC 恰好够快」—— 只要有一次慢了，await 之后就再也开不出窗口。
     * 因此这里先开一个 `about:blank` 空窗占住手势，RPC 返回后再填 URL。
     */
    const loginWindow = window.open('', LOGIN_WINDOW_NAME, LOGIN_WINDOW_FEATURES);
    console.log('[account-hub] account.create request, provider =', provider, '/ popup =', loginWindow);

    /** 关闭手势内开的空窗（幂等；已被拦截时为 no-op）。 */
    const closeLoginWindow = () => {
      try {
        if (loginWindow && !loginWindow.closed) loginWindow.close();
      } catch { /* 跨源或已被用户关闭：忽略 */ }
    };

    try {
      const res = await rpcCall('account.create', { provider });
      console.log('[account-hub] account.create response =', res);
      const accountId = res?.accountId;
      const loginUrl = res?.loginUrl;
      if (!accountId) {
        // 响应残缺（既没 accountId 也就无从轮询）：同样按错误处理并收窗。
        closeLoginWindow();
        setError('后端返回的账号信息不完整（缺少 accountId）。');
        setPhase('error');
        return;
      }
      if (!loginUrl) {
        // 后端没给地址：空窗留着就是一张白页，必须关掉。
        closeLoginWindow();
        setError('后端未返回登录地址（loginUrl 为空）。');
        setPhase('error');
        return;
      }
      if (loginWindow && !loginWindow.closed) {
        // 手势内开的那个窗口还在：直接把它导航到登录页。
        // 用 location.replace 而不是 href —— 空窗的 about:blank 不留在历史里，
        // 用户点「后退」不会退到一张白页。
        loginWindow.location.replace(loginUrl);
        console.log('[account-hub] login window navigated to', loginUrl);
      } else {
        // 空窗被激进拦截器挡下了。这里**不再**退化成 location.href：
        // 那会把 DSH 页面整个顶掉（用户丢失当前工作界面，且登录完成后
        // 无法回到设置页）—— 这正是本次要删除的兜底行为。
        // 改为在面板内渲染一个真实链接，由用户自己点击打开。
        setManualLogin({ url: loginUrl });
      }
      /**
       * 轮询的**收尾**动作（幂等）：停表 + 收窗 + 刷新账号列表。
       *
       * 三条终态路径共用它：登录成功、登录失败（宿主回 `done:true` + `error`）、
       * 5 分钟超时。早先只有成功路径收窗 —— 另两条都留下一张孤儿标签页，
       * 用户报障的「登录后多出残留标签页」正是它。
       *
       * `pollSettled` 让重复调用变成 no-op：成功收尾后那个 5 分钟定时器仍在，
       * 不加这道闸就会在 5 分钟后白跑一次 `loadAccounts`。
       */
      let pollSettled = false;
      const finishPolling = async () => {
        if (pollSettled) return;
        pollSettled = true;
        clearInterval(pollTimer);
        closeLoginWindow();
        await loadAccounts();
      };
      // 轮询等待登录完成
      const pollTimer = setInterval(async () => {
        try {
          const pollRes = await rpcCall('login.poll', { accountId, provider });
          if (!pollRes.done) return;
          // **失败终态**：宿主已结算（`done:true`）但带 `error`。
          // 必须与成功一样收窗 + 刷新，否则窗口会停在 127.0.0.1 上，
          // 用户既看不出登录已失败、也无法从面板得知原因。
          if (pollRes.error) {
            console.warn('[account-hub] login failed:', pollRes.error);
            if (mounted.current) {
              // 复用面板既有的通知行（probeNotice 的渲染块）而不是新造 UI：
              // 面板的 `error` + `phase='error'` 是整页替换，会把刚刷新的
              // 账号列表盖掉；这一行只在列表上方加一条可读原因。
              setProbeNotice({ tone: 'error', text: `登录失败：${pollRes.error}`, details: [] });
            }
          }
          await finishPolling();
        } catch { /* 继续轮询 */ }
      }, 1000);
      // 超时（5 分钟）：轮询期间宿主全程异常时也必须收窗，
      // 只清定时器会留下一张永远挂着的窗口。
      setTimeout(() => { void finishPolling(); }, 300000);
    } catch (caught) {
      console.error('[account-hub] create account failed:', caught);
      // 所有错误路径都要收掉空窗，否则就是一张永远白屏的孤儿窗。
      closeLoginWindow();
      if (caught?.code === 'login-in-progress') {
        // 宿主侧的 provider 级互斥（lobsterai / codearts）：已有未结算的登录会话。
        // 这不是「失败」，而是一句给用户的状态说明，故直接展示后端 message
        // （它已是可直接展示的中文文案），不加「登录失败：」前缀，也不再开窗。
        setError(caught.message || '已有登录进行中');
      } else {
        setError('登录失败：' + (caught?.message || '未知错误'));
      }
      setPhase('error');
    } finally {
      setCreating(false);
    }
  };

  const toggleAccount = async (accountId, enabled) => {
    try {
      await rpcCall('account.update', { accountId, patch: { enabled } });
      await loadAccounts();
    } catch (caught) {
      console.error('[account-hub] toggle failed:', caught);
    }
  };

  const deleteAccount = async (accountId) => {
    // 破坏性操作改走 `RiskConfirmation`（勾选确认才可执行），取代原生 `confirm()`。
    // 原生 confirm 是浏览器自绘的模态、样式不进主题体系，也无法表达「这是
    // 破坏性操作」。确认文案与迁移前逐字一致。
    setPendingDelete(accountId);
  };

  /** 用户已勾选「我了解」后才真正执行删除。 */
  const confirmDeleteAccount = async () => {
    const accountId = pendingDelete;
    setPendingDelete(null);
    setDeleteAcknowledged(false);
    if (accountId === null) return;
    try {
      await rpcCall('account.delete', { accountId });
      await loadAccounts();
    } catch (caught) {
      console.error('[account-hub] delete failed:', caught);
    }
  };

  return React.createElement('section', { 'aria-label': '账号管理' },
    React.createElement('div', { className: 'dim-ah-panelHead' },
      React.createElement('div', { className: 'dim-ah-panelTitleRow' },
        React.createElement('h2', { className: 'dim-ah-panelTitle' }, '账号管理'),
        React.createElement('div', { className: 'dim-ah-panelTitleActions' },
          React.createElement(Button, {
            variant: 'outline',
            size: 'sm',
            className: 'dim-ah-iconBtn',
            'aria-label': '模型列表',
            onClick: () => setShowModels(true),
          }, React.createElement('span', { 'aria-hidden': 'true' }, '☰')),
          canLoadCredits
            ? React.createElement(Button, {
                variant: 'outline',
                size: 'sm',
                className: 'dim-ah-iconBtn',
                'aria-label': '刷新积分',
                disabled: creditsLoading,
                onClick: () => void loadCredits(),
              }, React.createElement('span', {
                className: 'dim-ah-iconGlyph',
                'data-loading': creditsLoading ? 'true' : undefined,
                'aria-hidden': 'true',
              }, '⟳'))
            : null,
          supportsCredits
            ? React.createElement(Button, {
                variant: 'outline',
                size: 'sm',
                className: `dim-ah-iconBtn${claiming || allCheckedIn ? '' : ' dim-ah-iconBtn-light'}`,
                'aria-label': claiming ? '一键签到进行中' : allCheckedIn ? '全部已签' : '一键签到',
                disabled: claiming || accounts.length === 0 || allCheckedIn,
                onClick: () => void claimCredits(),
              }, React.createElement('span', { 'aria-hidden': 'true' }, claiming ? '◐' : allCheckedIn ? '✓' : '✉'))
            : null,
          React.createElement(Button, {
            variant: 'outline',
            size: 'sm',
            className: 'dim-ah-iconBtn dim-ah-iconBtn-light',
            'aria-label': '登录账号',
            onClick: () => void createAccount(),
            disabled: creating,
          }, React.createElement('span', { 'aria-hidden': 'true' }, '＋'))))),
    probeNotice
      ? React.createElement('div', {
          className: 'dim-ah-probeNotice',
          'data-tone': probeNotice.tone,
          role: 'status',
        },
        React.createElement('div', null, probeNotice.text),
        probeNotice.details.length > 0
          ? React.createElement('ul', { className: 'dim-ah-probeDetails' },
              probeNotice.details.map((d, i) => React.createElement('li', { key: i }, d)))
          : null)
      : null,
    claimNotice
      ? React.createElement(ClaimNotice, {
          tone: claimNotice.tone,
          text: claimNotice.text,
          details: claimNotice.details,
          // 暂不可签明细（`unavailable`）：旧通知对象没有该字段时为 undefined，
          // ClaimNotice 按「无」渲染 —— 既有路径的树逐元素不变。
          unavailableDetails: claimNotice.unavailableDetails,
          // 签到异常明细（`abnormal`，2026-09-24）：同上，缺失即按「无」渲染。
          abnormalDetails: claimNotice.abnormalDetails,
          // 无法判定明细（`undetermined`，2026-09-24）：同上。
          undeterminedDetails: claimNotice.undeterminedDetails,
        })
      : null,
    // 弹窗被拦截时的兜底入口。刻意**不做成按钮 + window.open(url)**：
    // 那需要在 onClick 里再开窗，而此刻用户手势是新鲜的、本可以成功 —— 但
    // 用手势内空窗的方案已经试过一次并失败了（拦截器策略），再失败一次用户
    // 就彻底没有入口。原生 <a href> 由浏览器自己处理导航，不受脚本开窗策略影响。
    manualLogin
      ? React.createElement('div', { className: 'dim-ah-manualLogin', role: 'status' },
          React.createElement('p', null, '登录窗口被浏览器拦截了。请点击下面的链接在浏览器中完成登录：'),
          React.createElement('a', {
            href: manualLogin.url,
            target: '_blank',
            rel: 'noreferrer noopener',
          }, '打开登录页面'))
      : null,
    // ── 消耗顺序 / 切换粒度 ──
    //
    // 位置：**账号卡片列表之前**（需求明确要求「面板顶部」）。两个选择器并排、
    // 各占一半宽，由样式表的 flex 决定；这里不需要任何宽度计算 —— 本节点与下面
    // 的账号区同处一个容器，宽度天然与卡片一致。
    //
    // 与账号列表的加载态无关：即使还没读到账号（loading / error / 空态），
    // 选择器也必须渲染出来（它是 provider 级配置，不依赖任何账号存在）。
    React.createElement(ConsumptionSelectors, {
      value: consumption,
      busy: consumptionBusy,
      onChange: (patch) => void updateConsumption(patch),
    }),
    phase === 'loading'
      ? React.createElement('div', { className: 'dim-ah-empty' }, '正在读取账号列表…')
      : phase === 'error'
        ? React.createElement('div', { className: 'dim-ah-empty', role: 'alert' },
            React.createElement('p', null, error),
            React.createElement(Button, { variant: 'outline', size: 'sm', className: 'dim-ah-btn-stable', onClick: loadAccounts }, '重新读取'))
        : accounts.length === 0
          ? React.createElement('div', { className: 'dim-ah-empty' },
              React.createElement('p', null, '尚未配置账号'),
              // 每个 provider（含 Qoder 两区）都是**在本面板浏览器登录**：
              // PAT 形态移除后文案只剩这一种，不再按登录形态分支。
              React.createElement('p', null, '点击"登录账号"进行浏览器登录。'))
          : React.createElement('div', null,
              // 排序提示整段已按用户要求删除；排序信息由卡片序号与拖拽手柄的位置表达。
              reorderError
                ? React.createElement('div', {
                    className: 'dim-ah-probeNotice',
                    'data-tone': 'warn',
                    role: 'alert',
                  }, React.createElement('div', null, `顺序保存失败：${reorderError}`))
                : null,
              accounts.map((account, index) => React.createElement(AccountCard, {
                key: account.id,
                account,
                index,
                // 面板级忙碌**含签到本身**（`claiming`）：一键签到或自动补签在跑时
                // 单片按钮必须 disabled，否则用户点下去只会被 `claimingRef` 挡掉
                // —— 那正是「点了没反应」的缺陷形态。`claiming` 是 state（可渲染），
                // `claimingRef` 是它的实时镜像（给闭包里的自动补签读）。
                busy: claiming,
                credits: credits[account.id],
                creditsLoading: creditsLoading && credits[account.id] === undefined,
                showCredits: canLoadCredits,
                showCheckin: supportsCredits,
                checkedIn: checkinsByAccount[account.id]?.checkedInToday === true,
                checkingThisAccount: checkinsByAccount[account.id]?.checking === true,
                onCheckin: (id) => void checkinAccount(id),
                onToggle: toggleAccount,
                onDelete: deleteAccount,
                // 提交在途时关掉拖拽，避免两次提交互相覆盖。
                drag: reordering ? { enabled: false } : dragPropsFor(account, index),
              }))),
    // 模型列表以 modal 渲染：它是覆盖层，放在账号区之后只是组件树的书写顺序，
    // 实际由 `Modal` 原语 portal 到 body、浮在整个面板之上，不挤占账号池的版面。
    showModels
      ? React.createElement(ModelListPanel, {
          provider,
          rpcCall,
          onClose: () => setShowModels(false),
        })
      : null,
    // 删除账号的确认弹窗（取代原生 `confirm()`）。它同样由 `RiskConfirmation`
    // portal 到 body，故渲染位置只影响组件树的书写顺序。
    //
    // ⚠️ 弹窗**不阻塞** `deleteAccount` 的调用：它现在只把待确认状态置位就返回，
    // 真正的 RPC 由弹窗的确认回调触发。
    pendingDelete !== null
      ? React.createElement(RiskConfirmation, {
          open: true,
          title: '删除账号',
          description: '确认删除此账号？关联的凭据也将被清除。',
          acknowledgeLabel: '我了解关联的凭据也会被清除',
          cancelLabel: '取消',
          closeLabel: '取消删除',
          confirmLabel: '删除',
          acknowledged: deleteAcknowledged,
          onAcknowledgedChange: setDeleteAcknowledged,
          onCancel: () => { setPendingDelete(null); setDeleteAcknowledged(false); },
          onConfirm: () => void confirmDeleteAccount(),
        })
      : null);
}

/**
 * 左侧导航里「自动路由」那一项的 id。
 *
 * ⚠️ 它与 `PROVIDERS` 的 id 空间**共用同一个 `selected`**（切换语义因此与 provider
 * 完全一致：`selectProvider` + version 重挂载），但值刻意等于宿主侧虚拟 provider 的
 * id（`src/auto-route.ts` 的 `AUTO_ROUTE_PROVIDER_ID`）：这个面板编辑的正是那个
 * 虚拟 provider 的模型列表，两处用同一个字符串才不会让人以为是两件事。
 * `PROVIDERS` 里没有这个值，故它不会与任何一个 provider tab 撞车。
 */
const AUTO_ROUTE_TAB_ID = 'auto-route';

/** 「自动路由」导航项与面板的显示名。 */
const AUTO_ROUTE_LABEL = '自动路由';

/** 自动路由总开关的简短悬停说明。 */
const AUTO_ROUTE_SWITCH_HELP = '开启后「自动路由」出现在 DSH 模型列表，其它 provider 从列表隐藏';

/** 该模型没有思考档位时，思考程度下拉的悬停说明。 */
const AUTO_ROUTE_EFFORT_NONE_HELP = '该模型无思考档位';

/**
 * 思考档位**在途**（`autoroute.model-info` 还没回来）时的悬停说明。
 *
 * 与「无思考档位」必须分开：在途时档位表还没有答案，说「该模型无思考档位」是
 * 一个**错误结论**（用户会据此以为这个模型不支持思考档位而放弃配置）。
 */
const AUTO_ROUTE_EFFORT_LOADING_HELP = '正在加载思考档位…';

/** 还没选供应商时，模型下拉的悬停说明。 */
const AUTO_ROUTE_PROVIDER_FIRST_HELP = '先选供应商，再选它下面的模型';

/** 还没选模型时，思考程度下拉的悬停说明。 */
const AUTO_ROUTE_MODEL_FIRST_HELP = '先选模型，再选它的思考档位';

/**
 * 思考程度下拉里「默认」那一项的 id。
 *
 * 空串是**哨兵值**，不是要写进配置的值：选中它 = **删掉** `entry.effort` 键
 * （缺省 = 该模型默认档）。写一个空串进去会被宿主写路径拒掉
 * （`assertValidAutoRouteConfig`：`effort` 存在但为空串即非法）。
 */
const AUTO_ROUTE_DEFAULT_EFFORT = '';

/** 「默认」档在界面上的文案。 */
const AUTO_ROUTE_DEFAULT_EFFORT_LABEL = '默认';

/** 自动模型定义 id 的自增种子（与时间戳一起保证同一次会话内不重复）。 */
let autoRouteIdSeed = 0;

/** 生成一个跨定义唯一的自动模型 id（客户端生成，RPC 寻址与排序都用它）。 */
function newAutoRouteDefinitionId() {
  autoRouteIdSeed += 1;
  return `auto-${Date.now().toString(36)}-${autoRouteIdSeed}`;
}

/**
 * 新自动模型的默认显示名：「自动模型 N」，且**不与已有定义重名**。
 *
 * 名字就是暴露给 DSH 的模型 id，写路径按「跨定义唯一」校验 —— 默认名撞车会让用户
 * 刚点「添加自动模型」就拿到一句保存失败。故这里从「已有条数 + 1」起逐个试到没被占用。
 */
function nextAutoRouteDefinitionName(definitions) {
  const used = new Set((definitions || []).map(definition => definition.name));
  let index = (definitions || []).length + 1;
  while (used.has(`自动模型 ${index}`)) index += 1;
  return `自动模型 ${index}`;
}

/** 档位缓存键：`provider` + `model` 两级唯一（同 key 不二次拉）。 */
function autoRouteEffortKey(provider, model) {
  return `${provider}\u0000${model}`;
}

/**
 * 自动路由编辑器里的一个下拉（供应商 / 模型 / 思考程度**同一个组件**）。
 *
 * 与 `ConsumptionSelect` 是**同一条路子**（自绘 `Menu` + 受控选中 + 锚点带可读名），
 * 但不复用那个组件：它的文案与用途是「消耗顺序」专用的（档位说明、`data-name`、
 * 等分布局），硬套会让三处调用点各带一堆无关 prop。这里只保留三档下拉共有的部分：
 * `options` / `value` / `busy` / `disabled` / `tooltip` / `onSelect`。
 *
 * ⚠️ **受控**：当前值只由 `value` 决定，选中动作只回调 `onSelect`。自动模型编辑器是
 * 「本地草稿 + 显式保存」，草稿由面板持有 —— 下拉自己留一份副本会让「面板被宿主
 * 返回值覆盖」与「下拉还停在旧值」同时成立。
 *
 * ⚠️ `value` 为空串时显示 `fallback`（如「选择供应商」）而不是空白锚点：空锚点看起来
 * 像坏掉的控件，而这里空值是一个**正常的中间态**（新加的条目还没选）。
 */
function AutoRouteSelect({ label, options, value, busy, disabled, fallback, tooltip, onSelect }) {
  const [open, setOpen] = React.useState(false);
  const current = options.find(option => option.id === value);
  const items = options.map(option => ({
    id: option.id,
    label: option.label,
    disabled: option.disabled === true,
  }));
  return withHoverTitle(React.createElement(Menu, {
    open,
    anchor: React.createElement(Button, {
      variant: 'outline',
      size: 'sm',
      className: 'dim-ah-arEntryMenu',
      // 可读名只来自这里（界面上三档下拉的可见文案只有当前值）。
      'aria-label': label,
      'aria-haspopup': 'menu',
      'aria-expanded': open,
      disabled: busy || disabled === true,
      icon: React.createElement(IconChevronDownOutlineRegular),
      onClick: () => setOpen(prev => !prev),
    }, current ? current.label : (value || fallback)),
    items,
    // 空串（「默认」/未选）不进 selectedId：`Menu` 的 undefined 才是「没有选中项」。
    selectedId: value || undefined,
    onSelect: (id) => { setOpen(false); onSelect(id); },
    onClose: () => setOpen(false),
    align: 'start',
  }), tooltip);
}

/**
 * 一条候选（def 卡片里的一行）：供应商 → 模型 → 思考程度三个联动下拉 + 删除 + 拖拽。
 *
 * ## 联动
 *
 * - 换供应商 ⇒ 清空模型与档位（旧的模型/档位属于上一个供应商，留着就是非法配置）；
 * - 换模型 ⇒ 清空档位（档位表是按模型问出来的）；
 * - 档位「默认」⇒ 清掉 `effort` 键（见 {@link AUTO_ROUTE_DEFAULT_EFFORT}）。
 *
 * 清空动作都在**面板**里做（`onSelectField`），本组件只负责把选中事件报上去 ——
 * 草稿的唯一所有者是面板。
 *
 * ## 档位按需拉取
 *
 * 档位**不随目录返回**（那要逐个模型问适配器），故这里在 provider+model 变化时
 * 请求一次 `autoroute.model-info`；缓存与去重在面板里（同一个 provider+model
 * 在多行里出现时只拉一次）。
 *
 * 未加载完成（`effortInfo === undefined`）时**不禁用**下拉：禁用一个还在加载的控件
 * 会让用户以为这个模型没有档位。加载完成后确实无档位（`efforts` 为空）才禁用，
 * 并挂上「该模型无思考档位」的悬停说明。
 */
function AutoRouteEntryRow({
  entry, index, catalog, effortInfo, busy, drag, onNeedEffort, onSelectField, onRemove,
}) {
  const providerGroup = catalog.find(group => group.id === entry.provider);
  const providerOptions = catalog.map(group => ({ id: group.id, label: group.name }));
  const modelOptions = (providerGroup ? providerGroup.models : []).map(model => ({ id: model.id, label: model.name }));
  const efforts = effortInfo && Array.isArray(effortInfo.efforts) ? effortInfo.efforts : [];
  // ⚠️ 判据必须带 `loading !== true`：请求在途时占位就是 `{ loading: true, efforts: [] }`，
  // 光看 `efforts.length === 0` 会把「还没问」误判成「问过了、没有档位」——
  // 用户会在下拉上读到「该模型无思考档位」这个**错误结论**。占位期间显示禁用态
  // （避免对着空列表选），但提示语是「正在加载思考档位…」。
  const effortLoading = effortInfo !== undefined && effortInfo.loading === true;
  const noEfforts = effortInfo !== undefined && !effortLoading && efforts.length === 0;
  // 「默认」= 不配 effort。有默认档数据时把档名带进悬停说明，用户才知道「默认」是什么。
  const defaultEffortHint = effortInfo && typeof effortInfo.defaultEffort === 'string'
    ? `不指定档位，用该模型的默认档（${effortInfo.defaultEffort}）`
    : '不指定档位，用该模型的默认档';
  const effortOptions = [{ id: AUTO_ROUTE_DEFAULT_EFFORT, label: withHoverTitle(React.createElement('span', null, AUTO_ROUTE_DEFAULT_EFFORT_LABEL), defaultEffortHint) }]
    .concat(efforts.map(effort => ({ id: effort, label: effort })));
  const effortTooltip = noEfforts
    ? AUTO_ROUTE_EFFORT_NONE_HELP
    : effortLoading
      ? AUTO_ROUTE_EFFORT_LOADING_HELP
      : (entry.model ? undefined : AUTO_ROUTE_MODEL_FIRST_HELP);

  // 挂载/换模型时按需拉一次档位（去重与缓存都在面板里）。
  React.useEffect(() => {
    onNeedEffort(entry.provider, entry.model);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [entry.provider, entry.model]);

  return React.createElement('div', {
    className: 'dim-ah-arEntryRow',
    'data-ar-entry': index,
    'data-dragging': drag.isDragging ? 'true' : undefined,
    'data-dropBefore': drag.isDropTarget && drag.dropPosition !== 'after' ? 'true' : undefined,
    'data-dropAfter': drag.isDropTarget && drag.dropPosition === 'after' ? 'true' : undefined,
    'data-drag-enabled': drag.enabled ? 'true' : 'false',
    draggable: drag.enabled ? 'true' : undefined,
    onDragStart: drag.onDragStart,
    onDragEnd: drag.onDragEnd,
    onDragOver: drag.onDragOver,
    onDrop: drag.onDrop,
  },
    drag.enabled
      ? React.createElement('span', {
          className: 'dim-ah-dragHandle',
          'aria-hidden': 'true',
        }, '⠿')
      : null,
    React.createElement(AutoRouteSelect, {
      label: '候选供应商',
      options: providerOptions,
      value: entry.provider,
      busy,
      fallback: '选择供应商',
      onSelect: (id) => onSelectField(index, 'provider', id),
    }),
    React.createElement(AutoRouteSelect, {
      label: '候选模型',
      options: modelOptions,
      value: entry.model,
      busy,
      // 供应商未选时模型无从选起（options 也是空的）。
      disabled: entry.provider === '',
      fallback: '选择模型',
      tooltip: entry.provider === '' ? AUTO_ROUTE_PROVIDER_FIRST_HELP : undefined,
      onSelect: (id) => onSelectField(index, 'model', id),
    }),
    React.createElement(AutoRouteSelect, {
      label: '思考程度',
      options: effortOptions,
      value: entry.effort === undefined ? AUTO_ROUTE_DEFAULT_EFFORT : entry.effort,
      busy,
      // 在途也禁用（占位里没有可选项），但提示语与「无档位」不同 —— 见 noEfforts。
      disabled: entry.model === '' || noEfforts || effortLoading,
      fallback: AUTO_ROUTE_DEFAULT_EFFORT_LABEL,
      tooltip: effortTooltip,
      onSelect: (id) => onSelectField(index, 'effort', id),
    }),
    React.createElement(Button, {
      variant: 'outline',
      size: 'sm',
      className: 'dim-ah-btn-danger',
      disabled: busy,
      onClick: () => onRemove(index),
    }, '删除'));
}

/**
 * 自动路由面板（左侧「自动路由」tab 的右侧内容）。
 *
 * ## 状态机：宿主权威值 + 本地草稿
 *
 * 面板里有**两份**状态，分界线是「服务端能不能逐操作接受」：
 *
 * | 状态 | 归属 | 写入方式 |
 * |---|---|---|
 * | `enabled`（总开关） | 宿主权威 | 切换即 `autoroute.set { enabled }`，成功后以**返回值**为准 |
 * | `models`（自动模型列表） | 本地草稿 | 所有编辑只改草稿；「保存」才 `autoroute.set { models }` |
 *
 * 为什么列表**不能**逐操作提交：宿主的写路径（`assertValidAutoRouteConfig`）会拒掉
 * 一切中间态 —— 新加的条目在用户逐级选完之前是空的、新加的定义在加条目之前 `entries`
 * 为空，两者都非法。逐操作提交等于「加一行就报一次错」。故列表走显式保存，
 * 服务端的拒绝消息（中文、点名到具体定义与字段）原样显示在面板内。
 *
 * ⚠️ **开关不做乐观更新**：与 `updateConsumption` / `ModelToggle` 同一条取舍 ——
 * 本地先翻会让「宿主拒绝写入」看起来像成功了。列表则相反：草稿本来就只是草稿，
 * 不存在「看起来已保存」的假象，故编辑立即反映、由脏标记与保存按钮承担责任。
 *
 * ## 关闭状态下面板仍可编辑
 *
 * `enabled === false` 只影响 DSH 的模型列表，不影响本面板的可用性：用户可以先把
 * 候选配好再打开。故这里**没有**任何「关闭即禁用编辑器」的分支。
 */
function AutoRoutePanel({ rpcCall }) {
  const [phase, setPhase] = React.useState('loading');
  const [loadError, setLoadError] = React.useState(null);
  // 总开关（宿主权威值）。
  const [enabled, setEnabled] = React.useState(false);
  const [switchBusy, setSwitchBusy] = React.useState(false);
  // 自动模型草稿。
  const [draft, setDraft] = React.useState([]);
  // 脏标记已随「修改即保存」改造移除：编辑操作自动提交（合法态才提交，见 editDraft）。
  const [saving, setSaving] = React.useState(false);
  // 保存失败的服务端中文消息（红色提示行）。
  const [saveError, setSaveError] = React.useState(null);
  // 供应商 × 模型两级目录（编辑器选择候选时拉一次）。
  const [catalog, setCatalog] = React.useState([]);
  // 目录拉取失败的原因（红色提示行 + 「重试」按钮）。目录是编辑器三个下拉的候选集，
  // 拉不到时下拉全空 —— 静默失败会让用户以为「这个插件没有任何模型可选」。
  const [catalogError, setCatalogError] = React.useState(null);
  // 档位缓存：`provider\0model` → `{ loading, efforts, defaultEffort? }`。
  const [efforts, setEfforts] = React.useState({});
  // 待确认删除的定义 id（`Modal` 二键确认，取代原生 confirm）。
  const [pendingDelete, setPendingDelete] = React.useState(null);
  /**
   * 拖拽状态（定义卡片与候选行**共用一份**，靠 `kind` + `defId` 区分作用域）。
   *
   * `defId` 对定义卡片是 `null`、对候选行是所属定义 id —— 少了它，从 A 卡片拖到
   * B 卡片的候选行上会被当成 A 内部的排序，插入线也会画在错误的行上。
   */
  const [drag, setDrag] = React.useState(null);
  const mounted = React.useRef(true);
  /**
   * 本地草稿的**同步镜像**（与 `draft` state 同值）。
   *
   * `saveModels` 的竞态判据要读「此刻」的草稿（请求在途时用户又改了一笔就不覆盖），
   * 而 `draft` state 在异步回调里读到的是**闭包快照**（发起时的值），必须靠 ref。
   */
  const draftRef = React.useRef([]);
  /**
   * 档位缓存的**权威副本**。
   *
   * 必须先于 await 写进 ref 再发请求：`setState` 是异步的，同一轮渲染里两行引用
   * 同一个 provider+model 时，只靠 state 会各发一次请求（去重失效）。ref 是同步的。
   */
  const effortsRef = React.useRef({});

  const loadConfig = React.useCallback(async () => {
    setPhase('loading');
    setLoadError(null);
    try {
      // 刻意**不带 provider**：自动路由是全局配置（见 src/types.ts 的
      // RpcAutoRouteGetRequest），照抄 consumption.get 的形态会误导读者。
      const res = await rpcCall('autoroute.get', {});
      if (!mounted.current) return;
      setEnabled(res?.enabled === true);
      setDraft(Array.isArray(res?.models) ? res.models : []);
      setPhase('ready');
    } catch (caught) {
      if (!mounted.current) return;
      setLoadError(caught?.message || '无法读取自动路由配置');
      setPhase('error');
    }
  }, [rpcCall]);

  /**
   * 拉供应商 × 模型目录。
   *
   * 失败**不阻断面板**：目录只是选择器的候选集，拉不到不该让面板变成错误页 ——
   * 已有的配置仍然要能看、能删、能改（与 loadConsumption 同一条取舍）。
   *
   * 但失败**必须可见**：目录拉不到时三个下拉的候选集全空，用户看到的是「没有一个
   * 模型可选」——那是一个与真相相反、且无从自行恢复的结论（唯一出路是重进面板）。
   * 故失败进 `catalogError` 并在面板上给一行红字 + 「重试」按钮。
   */
  const loadCatalog = React.useCallback(async () => {
    setCatalogError(null);
    try {
      const res = await rpcCall('autoroute.catalog', {});
      if (!mounted.current) return;
      setCatalog(Array.isArray(res?.providers) ? res.providers : []);
    } catch (caught) {
      console.warn('[account-hub] load auto-route catalog failed:', caught);
      if (!mounted.current) return;
      setCatalogError(caught?.message || '无法读取模型目录');
    }
  }, [rpcCall]);

  /**
   * 按需拉一个模型的档位（**同 provider+model 只拉一次**，见 effortsRef）。
   *
   * 宿主对无档位 / 未知模型 / 适配器抛错一律回 `{}`（那是**正常结果**，不是错误），
   * 故这里把「回空」当成「无档位」缓存下来，与真失败同一处置：都不重试，
   * 避免同一 key 在一次面板停留里反复打请求。
   */
  const requestEfforts = React.useCallback((provider, model) => {
    if (typeof provider !== 'string' || provider.length === 0) return;
    if (typeof model !== 'string' || model.length === 0) return;
    const key = autoRouteEffortKey(provider, model);
    if (Object.prototype.hasOwnProperty.call(effortsRef.current, key)) return;
    effortsRef.current[key] = { loading: true, efforts: [] };
    setEfforts({ ...effortsRef.current });
    rpcCall('autoroute.model-info', { provider, model }).then((res) => {
      if (!mounted.current) return;
      const info = { loading: false, efforts: Array.isArray(res?.efforts) ? res.efforts : [] };
      // `defaultEffort` 缺席 = 用 provider 自己的默认档，**不补一个猜测值**。
      if (typeof res?.defaultEffort === 'string') info.defaultEffort = res.defaultEffort;
      effortsRef.current[key] = info;
      setEfforts({ ...effortsRef.current });
    }).catch((caught) => {
      console.warn('[account-hub] load auto-route model info failed:', caught);
      if (!mounted.current) return;
      effortsRef.current[key] = { loading: false, efforts: [] };
      setEfforts({ ...effortsRef.current });
    });
  }, [rpcCall]);

  React.useEffect(() => {
    mounted.current = true;
    void loadConfig();
    void loadCatalog();
    return () => { mounted.current = false; };
    // 面板按 version 重挂载（见 AccountHubPage），故这里只需要跑一次。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /** 切换总开关：受控写法 —— 成功后以宿主返回值为准，失败保留原值。 */
  const toggleEnabled = async (next) => {
    setSwitchBusy(true);
    // 清掉上一次的失败：错误行不该跟着新的一次尝试继续挂着。
    setSaveError(null);
    try {
      const res = await rpcCall('autoroute.set', { enabled: next });
      if (!mounted.current) return;
      setEnabled(res?.enabled === true);
    } catch (caught) {
      console.error('[account-hub] update auto-route enabled failed:', caught);
      if (!mounted.current) return;
      // 开关**不做乐观更新**，被拒时弹回宿主值 —— 光弹回去等于「点了没反应」，
      // 故把原因写进面板内的红字行（与保存失败同一处出口）。
      setSaveError(caught?.message || '切换自动路由开关失败');
    } finally {
      if (mounted.current) setSwitchBusy(false);
    }
  };

  /**
   * 提交自动模型列表到宿主（修改即保存模式，取代旧的「显式保存」按钮）。
   *
   * 成功后用**宿主返回的**列表覆盖草稿（服务端可能补全/规整字段）；失败保留
   * 草稿与错误行 —— 用户继续编辑，下一次合法修改会再次触发提交。
   */
  const saveModels = async (nextDraft) => {
    // 中间态不提交：空 entries 卡片 / 空 provider-model 候选是编辑过程的合法
    // 暂态，但服务端会拒。此时只留本地，等下一条合法编辑一起提交。
    const submittable = Array.isArray(nextDraft) && nextDraft.length >= 0
      && nextDraft.every(def => def && typeof def.name === 'string' && Array.isArray(def.entries)
        && def.entries.length > 0
        && def.entries.every(entry => entry && typeof entry.provider === 'string' && entry.provider !== ''
          && typeof entry.model === 'string' && entry.model !== ''));
    if (!submittable) return;
    setSaving(true);
    setSaveError(null);
    try {
      const res = await rpcCall('autoroute.set', { models: nextDraft });
      if (!mounted.current) return;
      // 只有「宿主权威值与本地草稿不一致」才覆盖：用户在请求在途时又改了一笔，
      // 覆盖会把那一笔丢掉（改判为等下一次提交带上）。
      const current = draftRef.current;
      if (JSON.stringify(current) === JSON.stringify(nextDraft)) {
        setDraft(Array.isArray(res?.models) ? res.models : nextDraft);
      }
    } catch (caught) {
      console.error('[account-hub] save auto-route models failed:', caught);
      if (!mounted.current) return;
      // 服务端消息点名到具体定义与字段（中文），原样显示 —— 那是用户唯一能据以改正的信息。
      setSaveError(caught?.message || '保存失败');
    } finally {
      if (mounted.current) setSaving(false);
    }
  };

  /**
   * 编辑草稿的统一入口（修改即保存）：本地立即更新 + 异步提交宿主。
   *
   * 提交走 `saveModels(next)` 的合法性闸：中间态（空卡片/半选候选）只改本地。
   * 顺带清掉上一次的保存错误：错误行不该跟着新编辑继续挂着。
   */
  const editDraft = (updater) => {
    // 副作用不得进 state updater（React 要求纯函数：StrictMode 双跑会发两份
    // autoroute.set，并发渲染下 updater 也可能被丢弃重算）。先算 next 再提交。
    const next = typeof updater === 'function' ? updater(draft) : updater;
    draftRef.current = next;
    setDraft(next);
    setSaveError(null);
    void saveModels(next);
  };

  const addDefinition = () => {
    editDraft(prev => [...prev, {
      id: newAutoRouteDefinitionId(),
      name: nextAutoRouteDefinitionName(prev),
      // entries 为空是**允许的草稿态**：保存时会被服务端拒并给出点名错误，
      // 前端刻意不拦（用户需要先加卡片、再逐条加候选）。
      entries: [],
    }]);
  };

  const renameDefinition = (defId, name) => {
    editDraft(prev => prev.map(def => (def.id === defId ? { ...def, name } : def)));
  };

  const removeDefinition = (defId) => {
    editDraft(prev => prev.filter(def => def.id !== defId));
  };

  const addEntry = (defId) => {
    editDraft(prev => prev.map(def => (def.id === defId
      // provider / model 空串占位，由用户逐级选（写路径上这是非法中间态，
      // 正是「显式保存」存在的原因）。
      ? { ...def, entries: [...def.entries, { provider: '', model: '' }] }
      : def)));
  };

  const removeEntry = (defId, index) => {
    editDraft(prev => prev.map(def => (def.id === defId
      ? { ...def, entries: def.entries.filter((_, i) => i !== index) }
      : def)));
  };

  /** 改一条候选的某一级：换供应商/模型都要清掉下游取值（旧值属于上一级）。 */
  const setEntryField = (defId, index, field, value) => {
    editDraft(prev => prev.map(def => {
      if (def.id !== defId) return def;
      return {
        ...def,
        entries: def.entries.map((entry, i) => {
          if (i !== index) return entry;
          if (field === 'provider') return { provider: value, model: '' };
          if (field === 'model') return { provider: entry.provider, model: value };
          // 「默认」= 删掉 effort 键（空串写进去是非法的）。
          return value === AUTO_ROUTE_DEFAULT_EFFORT
            ? { provider: entry.provider, model: entry.model }
            : { provider: entry.provider, model: entry.model, effort: value };
        }),
      };
    }));
  };

  /** 按新 id 顺序重排定义（拖拽落点由 `orderAfterDrop` 算，见 account-order.js）。 */
  const applyDefinitionOrder = (orderedIds) => {
    const byId = new Map(draft.map(def => [def.id, def]));
    const next = orderedIds.map(id => byId.get(id)).filter(Boolean);
    // 理论不可达：id 集合来自本列表。真发生了也绝不写入半截列表。
    if (next.length !== draft.length) return;
    editDraft(() => next);
  };

  /** 按新的下标顺序重排某个定义内的候选。 */
  const applyEntryOrder = (defId, orderedIndexes) => {
    editDraft(prev => prev.map(def => {
      if (def.id !== defId) return def;
      const next = orderedIndexes.map(position => def.entries[Number(position)]).filter(Boolean);
      if (next.length !== def.entries.length) return def;
      return { ...def, entries: next };
    }));
  };

  /**
   * 构造一张卡片 / 一行的拖拽属性（少于两项时不启用：拖了也无处可落）。
   *
   * `kind` 区分「定义卡片之间」与「同一卡片内的候选行之间」两个作用域，`defId`
   * 再限定候选行只在自己卡片内落点。
   */
  const dragPropsFor = (kind, defId, key, count) => {
    if (count < 2) return { enabled: false };
    const active = drag !== null && drag.kind === kind && drag.defId === defId;
    return {
      enabled: true,
      isDragging: active && drag.sourceKey === key,
      isDropTarget: active && drag.targetKey === key && drag.sourceKey !== key,
      dropPosition: drag === null ? 'before' : drag.position,
      onDragStart: (event) => {
        // 候选行嵌在可拖定义卡内：阻止冒泡，避免父卡把 entry 拖拽覆盖成 def 拖拽。
        if (kind === 'entry') event.stopPropagation?.();
        setDrag({ kind, defId, sourceKey: key, targetKey: null, position: 'before' });
        // 必须设置 dataTransfer，否则 Firefox 根本不启动拖拽。
        try { event.dataTransfer.setData('text/plain', String(key)); } catch { /* 忽略 */ }
        if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move';
      },
      onDragEnd: (event) => {
        if (kind === 'entry') event.stopPropagation?.();
        setDrag(null);
      },
      onDragOver: (event) => {
        if (kind === 'entry') event.stopPropagation?.();
        if (drag === null || drag.kind !== kind || drag.defId !== defId) return;
        if (drag.sourceKey === key) return;
        // 必须 preventDefault，否则浏览器不把这里当作可放置区域。
        event.preventDefault();
        if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
        if (drag.targetKey !== key) setDrag({ ...drag, targetKey: key });
        const rect = event.currentTarget?.getBoundingClientRect?.();
        const position = dropPositionFromPointer(event.clientY, rect);
        if (position !== drag.position) setDrag({ ...drag, targetKey: key, position });
      },
      onDrop: (event) => {
        if (kind === 'entry') event.stopPropagation?.();
        event.preventDefault();
        if (drag === null || drag.kind !== kind || drag.defId !== defId) return;
        const sourceKey = drag.sourceKey;
        const position = drag.position;
        // 先清视觉状态再提交：拖拽反馈不该跟着任何后续渲染走。
        setDrag(null);
        if (sourceKey === key) return;
        if (kind === 'def') {
          const next = orderAfterDrop(draft.map(def => def.id), sourceKey, key, position);
          // null = 源与目标相同（或 id 不在列表里）：不改顺序。
          if (next !== null) applyDefinitionOrder(next);
          return;
        }
        const def = draft.find(item => item.id === defId);
        if (def === undefined) return;
        // 候选没有自己的 id（宿主契约里没有这个字段），故用**下标字符串**当排序键 ——
        // `orderAfterDrop` 只要求「一组唯一 id」，下标天然满足。
        const next = orderAfterDrop(def.entries.map((_, i) => String(i)), sourceKey, key, position);
        if (next !== null) applyEntryOrder(defId, next);
      },
    };
  };

  /** 渲染一个自动模型定义卡片（普通函数，不是组件：它要直接闭包面板状态）。 */
  const renderDefinition = (def, index) => {
    const cardDrag = dragPropsFor('def', null, def.id, draft.length);
    return React.createElement('div', {
      key: def.id,
      className: 'dim-ah-arCard',
      'data-ar-def': def.id,
      'data-dragging': cardDrag.isDragging ? 'true' : undefined,
      'data-dropBefore': cardDrag.isDropTarget && cardDrag.dropPosition !== 'after' ? 'true' : undefined,
      'data-dropAfter': cardDrag.isDropTarget && cardDrag.dropPosition === 'after' ? 'true' : undefined,
      draggable: cardDrag.enabled ? 'true' : undefined,
      'data-drag-enabled': cardDrag.enabled ? 'true' : 'false',
      onDragStart: cardDrag.onDragStart,
      onDragEnd: cardDrag.onDragEnd,
      onDragOver: cardDrag.onDragOver,
      onDrop: cardDrag.onDrop,
    },
      React.createElement('div', { className: 'dim-ah-arCardHead', 'data-drag-enabled': cardDrag.enabled ? 'true' : 'false' },
        cardDrag.enabled
          ? React.createElement('span', {
              className: 'dim-ah-dragHandle',
              'aria-hidden': 'true',
            }, '⠿')
          : null,
        React.createElement('span', { className: 'dim-ah-arOrder' }, String(index + 1)),
        React.createElement(Input, {
          className: 'dim-ah-arNameInput',
          value: def.name,
          disabled: saving,
          'aria-label': '自动模型名称',
          placeholder: '自动模型名称',
          onChange: (event) => renameDefinition(def.id, event?.target?.value ?? ''),
        }),
        React.createElement(Button, {
          variant: 'outline',
          size: 'sm',
          className: 'dim-ah-btn-danger',
          disabled: saving,
          onClick: () => setPendingDelete(def.id),
        }, '删除')),
      React.createElement('div', { className: 'dim-ah-arEntries' },
        def.entries.map((entry, entryIndex) => React.createElement(AutoRouteEntryRow, {
          key: entryIndex,
          entry,
          index: entryIndex,
          catalog,
          effortInfo: entry.provider !== '' && entry.model !== ''
            ? efforts[autoRouteEffortKey(entry.provider, entry.model)]
            : undefined,
          busy: saving,
          drag: dragPropsFor('entry', def.id, String(entryIndex), def.entries.length),
          onNeedEffort: requestEfforts,
          onSelectField: (rowIndex, field, value) => setEntryField(def.id, rowIndex, field, value),
          onRemove: (rowIndex) => removeEntry(def.id, rowIndex),
        })),
        React.createElement('div', { className: 'dim-ah-arAddEntry' },
          React.createElement(Button, {
            variant: 'outline',
            size: 'sm',
            className: 'dim-ah-btn-stable',
            disabled: saving,
            onClick: () => addEntry(def.id),
          }, '添加模型'))));
  };

  const pendingDefinition = pendingDelete === null
    ? null
    : draft.find(def => def.id === pendingDelete) || null;

  return React.createElement('section', { className: 'dim-ah-arPage', 'aria-label': '自动路由配置' },
    React.createElement('div', { className: 'dim-ah-arHead' },
      React.createElement('h2', { className: 'dim-ah-arTitle' }, '自动路由'),
      withHoverTitle(React.createElement(Switch, {
        checked: enabled,
        // 空列表时禁用：打开开关会把七个 provider 从 DSH 模型列表里隐藏，而自动路由
        // 自己又没有模型可暴露 ⇒ 一个分组都不剩。开关仍可点（宿主会照常接受）但结果
        // 是用户看不懂的空列表，故在源头挡住；开关提示统一保留指定的简短说明。
        disabled: switchBusy || draft.length === 0,
        label: '启用自动路由',
        onChange: (next) => void toggleEnabled(next),
      }), AUTO_ROUTE_SWITCH_HELP),
      withHoverTitle(React.createElement(Button, {
        variant: 'outline',
        size: 'sm',
        className: 'dim-ah-iconBtn',
        'aria-label': '添加自动模型',
        onClick: addDefinition,
      }, React.createElement(IconPlusOutlineRegular, { size: 16 })), '添加自动模型')),
    loadError !== null
      ? React.createElement('div', { className: 'dim-ah-arError', role: 'alert' },
          React.createElement('span', null, loadError),
          React.createElement(Button, {
            variant: 'outline',
            size: 'sm',
            className: 'dim-ah-btn-stable',
            onClick: () => void loadConfig(),
          }, '重新读取'))
      : null,
    // 保存失败的服务端消息：点名到具体定义与字段，故整行原样显示。
    saveError !== null
      ? React.createElement('div', { className: 'dim-ah-arError', role: 'alert' }, saveError)
      : null,
    // 目录拉取失败：编辑器的三个下拉会全空，必须说清原因并给一条恢复路径。
    catalogError !== null
      ? React.createElement('div', { className: 'dim-ah-arError', role: 'alert' },
          React.createElement('span', null, catalogError),
          React.createElement(Button, {
            variant: 'outline',
            size: 'sm',
            className: 'dim-ah-btn-stable',
            onClick: () => void loadCatalog(),
          }, '重试'))
      : null,
    phase === 'loading'
      ? React.createElement('div', { className: 'dim-ah-arEmpty' }, '正在读取自动路由配置…')
      : draft.length === 0
        ? React.createElement('div', { className: 'dim-ah-arEmpty' },
            React.createElement('p', null, '尚未配置自动模型'),
            React.createElement('p', null, '自动模型是一个暴露给 DSH 的模型名，背后是一串按顺序降级的候选。'))
        : React.createElement('div', { className: 'dim-ah-arList' }, draft.map(renderDefinition)),
    // 删除定义的确认弹窗（单条定义属轻量破坏，二键确认即可，不用勾选闸）。
    pendingDefinition !== null
      ? React.createElement(Modal, {
          open: true,
          onClose: () => setPendingDelete(null),
          title: '删除自动模型',
          closeLabel: '取消删除',
          description: `确认删除自动模型『${pendingDefinition.name}』？它的 ${pendingDefinition.entries.length} 条候选将一并移除。`,
          footer: [
            React.createElement(Button, {
              key: 'cancel',
              variant: 'outline',
              onClick: () => setPendingDelete(null),
            }, '取消'),
            React.createElement(Button, {
              key: 'confirm',
              variant: 'primary',
              className: 'dim-ah-btn-stable',
              onClick: () => { setPendingDelete(null); removeDefinition(pendingDefinition.id); },
            }, '删除'),
          ],
        })
      : null);
}

/** commit sha 的展示形态：前 8 位（与 git 自己的短 sha 同款）。 */
function shortSha(sha) {
  // 服务端契约保证是 40 位十六进制串；这里仍做形状防御 —— 提示行是纯展示，
  // 不该因为一个字段缺失就把整页渲染打崩（白屏的代价远大于显示一个「未知」）。
  return typeof sha === 'string' && sha.length > 0 ? sha.slice(0, 8) : '未知';
}

/**
 * 页面级「检查更新 / 一键更新」提示行。
 *
 * 只有需要提示行承载的相位才渲染：`available` / `applying` / `applied` / `failed`。
 * `idle`（含静默检查失败后的回落）、`checking` 与 `latest` 一律返回 null；
 * `latest` 的轻量反馈由页面标题旁的 Tag 展示。
 *
 * 外观复用面板级通知行 `.dim-ah-probeNotice`（同一个 `data-tone` 取值域），
 * 不新造视觉；外层 `.dim-ah-updateBar` 只负责与 `.dim-ah-header` 同宽同内边距。
 */
function UpdateNotice({ update, logOpen, onApply, onToggleLog }) {
  /** 与 `.dim-ah-probeNotice` 的 tone 域一致；失败才换成错误档。 */
  let tone = 'ok';
  let role = 'status';
  let children = null;

  if (update.phase === 'available' || update.phase === 'applying') {
    // 「可更新」与「更新中」共用同一块版面：按钮**原地**从「立即更新」转成禁用的
    // 「更新中…」，位置不跳 —— 用户点下去之后视线不必重新找。
    const applying = update.phase === 'applying';
    children = [
      React.createElement('div', { key: 'title' }, `发现新版本：${update.latestTitle}`),
      React.createElement('div', { key: 'sha' },
        `当前 ${shortSha(update.currentSha)} → 最新 ${shortSha(update.latestSha)}`),
      React.createElement(Button, {
        key: 'apply',
        variant: 'primary',
        size: 'sm',
        className: 'dim-ah-btn-stable',
        disabled: applying,
        onClick: onApply,
      }, applying ? '更新中…' : '立即更新'),
    ];
  } else if (update.phase === 'applied') {
    children = [
      React.createElement('div', { key: 'done' },
        `已更新到 ${shortSha(update.currentSha)}，建议重启会话生效`),
      // 日志折叠：仓库里没有原生 details/summary 范式（控件一律走 ui-primitives），
      // 故用最简的展开/收起 state + 一枚 outline 按钮。日志为空时整块不渲染。
      update.log
        ? React.createElement('div', { key: 'log' },
            React.createElement(Button, {
              variant: 'outline',
              size: 'sm',
              className: 'dim-ah-btn-stable',
              onClick: onToggleLog,
            }, logOpen ? '收起日志' : '查看完整日志'),
            logOpen
              ? React.createElement('pre', { className: 'dim-ah-updateLog' }, update.log)
              : null)
        : null,
    ];
  } else if (update.phase === 'failed') {
    // 失败显示**服务端原文**：提示行只加「更新失败：」前缀说明是哪个操作失败了，
    // message 本身一字不改 —— 改写会把唯一可诊断的线索洗掉。
    tone = 'error';
    role = 'alert';
    children = [React.createElement('div', { key: 'error' }, `更新失败：${update.error}`)];
  }

  if (children === null) return null;

  return React.createElement('div', { className: 'dim-ah-updateBar' },
    React.createElement('div', {
      className: 'dim-ah-probeNotice',
      'data-tone': tone,
      role,
    }, children));
}

export function AccountHubPage({ rpcCall }) {
  const [selected, setSelected] = React.useState(PROVIDERS[0].id);
  // 每次切换 provider 时递增版号，强制重新挂载 ProviderPanel 触发 loadAccounts
  const [version, setVersion] = React.useState(0);
  /**
   * 更新状态机：`idle` / `checking` / `available` / `latest` / `applying` /
   * `applied` / `failed`（字段 `latestTitle` / `latestSha` / `currentSha` /
   * `log` / `error` 按相位出现）。
   *
   * 落在**页面级**而不是 ProviderPanel：更新检查的是插件自身版本，七个供应商
   * 面板与自动路由共用同一个事实 —— 逐个面板各挂一份只会得到八份互相矛盾的提示。
   */
  const [update, setUpdate] = React.useState({ phase: 'idle' });
  /** 「查看完整日志」的展开态（apply 成功后才有意义）。 */
  const [updateLogOpen, setUpdateLogOpen] = React.useState(false);
  /** 卸载后不再 setState（异步检查 / 更新返回时组件可能已经不在了）。 */
  const updateAliveRef = React.useRef(true);
  /**
   * 供应商折叠组：**默认展开**（用户拍板「默认不折叠」），且**不持久化** ——
   * 刷新页面回到展开态，不引入任何存储面。
   *
   * 折叠只影响七个导航项**可不可见**：`selected` 与 `version` 一行不动，
   * 故右侧面板既不会切换、也不会重挂载（折叠不是选择）。
   */
  const [providersOpen, setProvidersOpen] = React.useState(true);

  const selectProvider = (id) => {
    setSelected(id);
    setVersion(v => v + 1);
  };

  /**
   * 检查更新。**失败静默**是本方法的性质，不是某一处的选择：挂载时的自动检查
   * 尤其不能打扰用户 —— 他没有主动做任何事，一次后台请求失败不该在页面顶部留提示。
   * 故失败只写一条 console.warn 并回落到 idle（提示行随之消失）。
   */
  const checkUpdate = async () => {
    setUpdate({ phase: 'checking' });
    let res;
    try {
      res = await rpcCall('update.check', {});
    } catch (caught) {
      console.warn('[account-hub] update check failed:', caught);
      if (updateAliveRef.current) setUpdate({ phase: 'idle' });
      return;
    }
    if (!updateAliveRef.current) return;

    if (res?.hasUpdate === true) {
      setUpdate({
        phase: 'available',
        latestTitle: res.latestTitle,
        latestSha: res.latestSha,
        currentSha: res.currentSha,
      });
      return;
    }

    // 无更新时保留 latest 状态；标题旁的 Tag 直到用户再次检查才切换。
    setUpdate({ phase: 'latest', currentSha: res?.currentSha });
  };

  /**
   * 一键更新。与检查相反：这是用户**主动**发起的动作，失败必须可见 ——
   * 提示行显示服务端原始 message（`unwrapRpcResult` 抛出的 `caught.message`），
   * 不做二次包装或改写。
   */
  const applyUpdate = async () => {
    setUpdateLogOpen(false);
    // 保留 available 相位里的 latestTitle / sha：更新中的提示行要继续显示它在装哪个版本。
    setUpdate(prev => ({ ...prev, phase: 'applying' }));
    let res;
    try {
      res = await rpcCall('update.apply', {});
    } catch (caught) {
      if (updateAliveRef.current) {
        setUpdate({ phase: 'failed', error: caught?.message || '更新失败' });
      }
      return;
    }
    if (!updateAliveRef.current) return;

    setUpdate({
      phase: 'applied',
      previousSha: res?.previousSha,
      currentSha: res?.currentSha,
      log: typeof res?.log === 'string' ? res.log : '',
    });
  };

  /**
   * 挂载后自动**静默**检查一次：只在真有更新时才出现提示行。
   *
   * deps 为空 ⇒ 整页生命周期内只跑一次。切 provider 不会重跑：`AccountHubPage`
   * 自己不重挂载（重挂载的是右侧面板）。cleanup 标记「已卸载」——
   * 异步结果回来时组件可能已经不在了，那时 setState 是纯浪费。
   */
  React.useEffect(() => {
    updateAliveRef.current = true;
    void checkUpdate();
    return () => {
      updateAliveRef.current = false;
    };
  }, []);

  return React.createElement('section', { className: 'dim-ah-page', 'aria-label': '账号中心' },
    React.createElement('header', { className: 'dim-ah-header' },
      React.createElement('div', { className: 'dim-ah-brand' },
        React.createElement('div', { className: 'dim-ah-brandTitleRow' },
          React.createElement('strong', { className: 'dim-ah-brandName' }, '账号中心'),
          update.phase === 'latest'
            ? React.createElement(Tag, { tone: 'success' }, '已是最新')
            : null),
        React.createElement('p', { className: 'dim-ah-brandDesc' }, 'Provider 凭据管理与多账号支持')),
      // 「检查更新」：更新的是**插件自身**，与任何 provider 都无关，故入口在页面
      // 顶部（header 右侧）而不是某个面板的标题行里 —— 七个面板各挂一个只会得到
      // 八份互相矛盾的提示。图标按钮**不带悬停提示**：本插件的按钮提示已按用户
      // 要求整体删除，可读名由 aria-label 提供。
      React.createElement(Button, {
        variant: 'outline',
        size: 'sm',
        className: 'dim-ah-iconBtn',
        'aria-label': '检查更新',
        // 检查中 / 更新中禁止重复触发；latest 用标题旁标签表示，其余结果走下方提示行。
        disabled: update.phase === 'checking' || update.phase === 'applying',
        onClick: () => void checkUpdate(),
      }, React.createElement('span', { 'aria-hidden': 'true' }, '⇩'))),
    // 页面级更新提示行：header 之下、两栏之上。它不属于任何 provider，故放在
    // `.dim-ah-layout` **之外**（切 provider 时既不重挂载、也不会消失）。
    React.createElement(UpdateNotice, {
      update,
      logOpen: updateLogOpen,
      onApply: () => void applyUpdate(),
      onToggleLog: () => setUpdateLogOpen(prev => !prev),
    }),
    React.createElement('div', { className: 'dim-ah-layout' },
      React.createElement('nav', { className: 'dim-ah-rail', role: 'tablist', 'aria-label': 'Provider 导航' },
        // 组标题走 ui-primitives 的 DisclosureRow：`expandOnRowClick` 让整行成为
        // 折叠目标，它同时给出 `aria-expanded`（无障碍要的那一条）。
        React.createElement(DisclosureRow, {
          icon: React.createElement(IconApiOutlineRegular),
          title: '供应商',
          open: providersOpen,
          expandable: true,
          expandOnRowClick: true,
          onToggle: () => setProvidersOpen(prev => !prev),
        },
        // 折叠时 DisclosureRow 不渲染 children ⇒ 七个 tab 整体不在树里。
        React.createElement('div', { className: 'dim-ah-providerGroup' },
          PROVIDERS.map(p => React.createElement('button', {
            key: p.id,
            type: 'button',
            role: 'tab',
            className: 'dim-ah-provider',
            'aria-selected': p.id === selected,
            onClick: () => selectProvider(p.id),
          },
          React.createElement(ProviderLogo, { provider: p.id }),
          React.createElement('span', null,
            React.createElement('strong', null, p.label)))))),
        // 「自动路由」入口：**在折叠组之外**、组下方。
        //
        // 刻意不放进 `DisclosureRow` 的 children 里：那个组的语义是「供应商」，
        // 折叠它应当只收起七个 provider tab。把自动路由塞进去会让「折叠供应商」
        // 顺手藏掉一个与供应商无关的入口 —— 它编辑的是全局配置，不属于任何 provider。
        React.createElement('button', {
          type: 'button',
          role: 'tab',
          className: 'dim-ah-provider',
          'aria-selected': selected === AUTO_ROUTE_TAB_ID,
          onClick: () => selectProvider(AUTO_ROUTE_TAB_ID),
        },
        // 图标容器与 provider 同形（.dim-ah-providerIcon），配色走 `ar` 类：
        // 它不是品牌标识，故**不吃**品牌色豁免，颜色来自 token
        // （--dsw-alias-state-business-primary，语义 = 「本插件自己的功能」而非
        // 某个第三方产品的品牌色）。
        React.createElement('span', { className: 'dim-ah-providerIcon ar' },
          React.createElement(IconBranchOutlineRegular, { size: 20 })),
        // 与七个 provider 项**逐字同形**（裸 span + strong），不额外加一层标签类
        // （曾经的 `.dim-ah-providerLabel`，已删）：那个类名是单数，多一个类就是八个
        // 导航项里唯一的异类，而两处的文本截断行为应当一致。
        React.createElement('span', null,
          React.createElement('strong', null, AUTO_ROUTE_LABEL)))),
      React.createElement('main', {
        className: 'dim-ah-panel',
        role: 'tabpanel',
      },
      // 与 provider 面板**同一套切换语义**：只有被选中的那一个挂载，
      // 且 key 带 version ⇒ 每次点选都重挂载（自动路由面板据此重新拉配置，
      // 不必自己实现「切回来要刷新」）。
      selected === AUTO_ROUTE_TAB_ID
        ? React.createElement(AutoRoutePanel, { key: AUTO_ROUTE_TAB_ID + '-' + version, rpcCall })
        : PROVIDERS.map(p => p.id === selected
          ? React.createElement(ProviderPanel, {
              key: p.id + '-' + version,
              provider: p.id,
              rpcCall,
            })
          : null))));
}
